-- 效果图提示词库(2026-09-17 创始人:「一定要看参考站的规范」「工具都很强大,提示词不行,AI图就很惨」「提示词方面一定要优化」)。
-- render_prompts:从 F:/0cosmetic/素材/参考站AI效果图-715张/ 抽 72 张,fleet.vision 逐张反推(tools/render/_look.py),src='lainuoniao';
--   category 与 packaging.type 对齐:dropper-bottle / jar / tube / pump-bottle / gift-set / lifestyle(该编号段实际混品类,归类以任务标签为准);
--   sample_img 先写本地相对路径(素材/参考站AI效果图-715张/NN.jpg),未传 R2;后续传了改成 /media/{id} 即可。后台「图片转提示词」存入的行 src='reverse'。
-- render_templates:每类 2 个模板,占位 {product} {material} {color} {cap},由 tools/render/pilot.py 与 /api/admin/prompts(op=render)套用。幂等。
CREATE TABLE IF NOT EXISTS render_prompts (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  category   TEXT NOT NULL,
  scene      TEXT, prompt_en TEXT NOT NULL, prompt_zh TEXT,
  lighting   TEXT, camera TEXT, props TEXT, palette TEXT, mood TEXT,
  src        TEXT NOT NULL DEFAULT 'reverse',   -- lainuoniao / reverse
  sample_img TEXT,                              -- /media/{id} 或本地相对路径
  score      INTEGER,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_render_prompts_cat ON render_prompts(category);
CREATE TABLE IF NOT EXISTS render_templates (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  category    TEXT NOT NULL,
  name        TEXT NOT NULL,
  template_en TEXT NOT NULL,
  template_zh TEXT,
  notes       TEXT
);
DELETE FROM render_prompts WHERE src='lainuoniao';
DELETE FROM render_templates;
