INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','粉色渐变无缝背景，粉色圆形阶梯展台，产品围绕冰淇淋球陈列','Commercial beauty product photography of three matte squeeze lip care tubes in mocha brown, dusty rose, and cream nude, artfully arranged around a pink ceramic bowl filled with three scoops of vanilla, chocolate, and strawberry ice cream. The products rest on tiered pink circular platforms against a seamless soft pink gradient backdrop. Soft diffused studio lighting from upper left with gentle fill, subtle edge rim light defining tube shapes, no harsh shadows. Slight elevated three-quarter angle, 85mm equivalent lens, sharp focus across the product group with delicate depth-of-field separation. Clean minimalist composition, high-end cosmetic campaign aesthetic, pastel-toned luxury mood, softly rendered textures with a touch of dreamy sweetness.','商业美妆产品摄影，三支哑光软管唇部护理产品，颜色为摩卡棕、灰粉和奶油杏色，围绕一只装满香草、巧克力和草莓冰淇淋球的粉色陶瓷碗艺术陈列。产品摆放在粉色圆形阶梯展台上，背景为无缝柔粉色渐变。柔光摄影棚布光，主光从左上角入射，配合柔和补光，管身边缘有微妙轮廓光，无硬阴影。微俯四分之三视角，85mm等效镜头，产品组整体清晰，景深层次细腻过渡。构图干净极简，高端美妆广告美学，柔和色调的奢华质感，带一丝梦幻甜美氛围。','柔光主光从左上前方入射，整体光线均匀柔和，边缘轻微轮廓光勾勒管身，无反光板抢镜','微俯视角约30度，中景构图，85mm等效焦段，整体清晰略有景深过渡突出前景产品','粉色陶瓷碗，三色冰淇淋球（巧克力、香草、草莓），粉色圆形阶梯展台，哑光软管唇部护理产品','脏粉色，奶油白，巧克力棕，玫瑰粉，白色盖头，淡杏色','甜美俏皮，梦幻少女感，奢华精致，食欲感，柔焦清新','lainuoniao','素材/参考站AI效果图-715张/01.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','长满青苔的原木森林地面，周围散落着蕨类植物、小碎石和白色野花','Commercial product photography of a matte white cosmetic lotion bottle with a mint green cap, featuring a blank minimalist label, resting on a moss-covered fallen log. The scene is set in a serene forest environment surrounded by lush green ferns, tiny white wildflowers, and scattered smooth river stones. Dappled sunlight filters through the canopy, creating soft, organic shadows on the product. Shot from a high angle with an 85mm lens, shallow depth of field, soft focus background, high resolution, 8k, hyper-realistic textures.','商业产品摄影，哑光白色化妆品乳液瓶，配有薄荷绿瓶盖，标签为空白极简风格，放置在长满青苔的原木上。场景设定在宁静的森林环境中，周围环绕着茂盛的绿色蕨类植物、细小的白色野花和散落的圆润河石。斑驳的阳光透过树冠洒落，在产品展示出柔和的自然阴影。高角度拍摄，使用85mm镜头，浅景深，背景柔焦，高分辨率，8k，超写实质感。','柔和的森林斑驳自然光，主光从上方透过树叶洒下，形成细腻的光影，瓶身带有微妙的边缘轮廓光','俯视特写，85mm焦段，f/2.8大光圈，浅景深，背景梦幻虚化','苔藓，枯木，蕨类叶片，白色小野花，干燥种子头，圆润鹅卵石','薄荷绿，乳白色，森林绿，泥土棕，米色，灰色','自然，清新，有机，宁静，高端，治愈','lainuoniao','素材/参考站AI效果图-715张/12.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','编织篮置于湖畔草地上，篮内盛有青苹果、洋甘菊雏菊与化妆品，背景为波光粼粼的湖水','Three premium cosmetic bottles and one jar in frosted mint-green glass with matte pastel green caps and silver metallic bands, arranged elegantly inside a rustic woven wicker basket alongside fresh green apples and delicate white chamomile daisies, placed on lush green grass beside a gently rippling lake, bathed in warm golden hour sunlight with soft directional side lighting creating subtle rim highlights and gentle shadows, shallow depth of field with softly blurred water background, slightly elevated camera angle looking into the basket, clean commercial product photography aesthetic, high-end beauty packaging presentation, fresh and organic mood, softly retouched with natural color grading','三支高端化妆品瓶与一支罐体，采用磨砂薄荷绿玻璃搭配哑光 pastel 绿色瓶盖与银色金属细环装饰，优雅陈列于复古藤编篮中，周围点缀新鲜青苹果与精致白色洋甘菊雏菊，篮子置于湖畔翠绿草地上，沐浴在温暖黄金时段自然侧光中，形成柔和轮廓高光与轻柔阴影，浅景深虚化背景湖面，稍高角度俯拍入篮，干净的商业产品摄影质感，高端美妆包装呈现风格，清新有机氛围，自然调色轻度后期修饰','黄金时段暖色自然光从侧上方照射，柔中带暖调高光，产品边缘泛柔光轮廓，水面反射环境光','中高角度俯拍进入篮内，85mm焦段，浅景深使背景水面柔和虚化，主体锐利清晰','柳条编织篮、青苹果、白色洋甘菊雏菊、磨砂玻璃瓶罐、哑光薄荷绿瓶盖、金属细环装饰','薄荷绿、藤编暖棕、草叶绿、雏菊白与鹅黄、湖水蓝绿、暖金高光','清新自然、有机纯净、阳光治愈、轻奢护肤、田园诗意','lainuoniao','素材/参考站AI效果图-715张/22.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','柔和垂坠的米色织物背景搭配白色满天星花枝，营造温馨有机的静物场景','A cosmetic glass dropper serum bottle with a speckled terrazzo-textured cream finish, silver metallic dropper cap, and white rubber bulb, centered on a raw-edged white limestone slab. Draped nude silk fabric flows behind as a soft background, with delicate baby''s breath flower stems entering from the upper right. Warm diffused natural window light casts gentle striped shadow patterns across the fabric, with soft rim light outlining the bottle. Shot at a slight downward angle, 50mm lens, shallow depth of field with creamy bokeh. Clean minimalist composition, luxurious editorial beauty product photography, soft warm color grading, high-end cosmetic commercial style.','一款带有斑点水磨石纹理奶油色瓶身的玻璃精华滴管瓶，银色金属滴管盖与白色胶头，居中置于一块粗边白色石灰石台之上。身后垂坠着裸色丝绸织物作为柔和背景，右上角延伸出细嫩的满天星花枝。温暖漫射的自然窗光在织物上投下轻柔的百叶窗式条纹光影，产品边缘勾勒柔和轮廓光。轻微俯拍视角，50mm镜头，浅景深带来奶油般虚化效果。构图极简干净，奢华杂志级美妆产品摄影，暖色调柔和调色，高端化妆品商业风格。','自然窗光侧后方入射，光线柔和漫射，织物背景呈现百叶窗式条纹光影，产品边缘带柔和轮廓光与反光板补光','中景俯拍约30度视角，50mm定焦镜头，浅景深，主体清晰、背景花枝与前景织物微微虚化','白色粗糙切面石台、满天星花枝、米色垂坠丝绸质感布料','奶油白、暖沙色、米驼色、银色金属、淡绿、暖灰棕','温柔、精致、有机奢华、极简主义、自然清新、文艺氛围','lainuoniao','素材/参考站AI效果图-715张/33.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','粉色纯色背景，多支红色管状化妆品悬浮排列','Commercial product photography of floating red cosmetic tubes against a soft pastel pink background. Dynamic arrangement with splashing light pink cream and droplets. Glossy tube surfaces with white typography. Soft studio lighting with even illumination and subtle rim highlights. Clean, minimalist aesthetic. High-resolution, sharp focus, professional beauty advertising style. Blank label design, vibrant red and pink color palette.','商业产品摄影，悬浮的红色化妆品管置于柔和的淡粉色背景前。动态排列，伴有浅粉色奶油飞溅和液滴。光滑的管身表面印有白色字体。柔和的影棚灯光，照明均匀，边缘带有微妙的高光。干净、极简的美学风格。高分辨率，对焦清晰，专业美妆广告风格。空白标签设计，鲜艳的红色和粉色配色。','柔和影棚光，主光均匀照亮主体，边缘有高光轮廓，白色反光板补光，奶油质感反光明显','平视角度，中焦镜头，景深清晰，商业产品摄影构图','红色圆柱形护肤品管，浅粉色奶油飞溅，透明液滴','亮红色，淡粉色，白色，奶油粉','活力，清新，时尚，动感，高端美妆','lainuoniao','素材/参考站AI效果图-715张/44.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','明亮通透的自然光感场景，柔焦背景搭配清新植物与水果元素，营造纯净轻盈的护肤氛围','A commercial beauty product photograph of a translucent pale green spray mist bottle with a blank label, held elegantly by a fair-skinned hand releasing a fine nano-mist spray. The scene is bright and airy with soft natural high-key lighting, set against a dreamy blurred background of white magnolia flowers and sliced guava fruit with visible water droplets glistening on petals and skin. Macro close-ups showcase mist particles and dewy skin texture. Shot on 85mm lens with shallow depth of field for product focus and creamy bokeh. Post-processing emphasizes freshness, luminosity, and a clean editorial beauty aesthetic with soft color grading.','商业美妆产品摄影，一只白皙的手优雅地握着一瓶半透明淡薄荷绿喷雾瓶，瓶身标签为空白，正释放出细腻的纳米级喷雾。场景明亮通透，采用高调柔光自然光照明，背景为梦幻虚化的白色玉兰花与切开的番石榴，花瓣和皮肤上点缀着晶莹水珠。微距特写展现喷雾颗粒与水润肤质质感。使用85mm镜头拍摄，浅景深突出产品主体，背景奶油化散景。后期处理强调清新通透感与洁净的美容编辑风格，色调柔和。','高调柔光为主，自然漫射光从右上方入射，搭配反光板补光，喷雾与水滴呈现晶莹高光，皮肤区域使用柔和美容光','近景到中景镜头，浅景深虚化背景，微距捕捉水滴细节与喷雾雾化效果，平视略带俯视角度','番石榴（整果与切片）、白色玉兰花、透明水珠、晶莹剔透玻璃珠装饰、喷雾细腻雾气','淡薄荷绿、樱花粉、纯白、西瓜红、嫩叶绿、暖木色','清新、纯净、轻盈、水润、高级感、日系美容、通透、自然主义','lainuoniao','素材/参考站AI效果图-715张/56.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','红色礼盒与缎带点缀的奢华节日产品展示台面，底部叠加红色细闪颗粒材质','Professional commercial product photography of four luxury cosmetic containers in rich red transparent glass with polished silver caps and cream-colored blank labels, arranged on a deep red surface alongside wrapped red gift boxes adorned with satin ribbons edged in fine gold thread, a textured red glitter strip at the lower foreground, soft diffused top-left studio lighting creating gentle specular highlights on metallic surfaces, 45-degree overhead angle, symmetrical flat-lay composition, ultra-sharp focus across all elements, high-end beauty advertising aesthetic, HDR refined tones, no visible branding or text.','专业商业产品摄影，四只奢华红色透明玻璃化妆品容器配抛光银色瓶盖与奶油色空白标签，陈列于深红色台面上，旁侧摆放系有金边缎带的红色礼品盒，底部为红色细闪纹理装饰带，柔和漫射顶光从左上方投射在金属表面形成细腻高光，45度俯拍角度，对称平铺构图，全画面超清锐利，高端美妆广告质感，HDR精调色调，无任何品牌或文字露出。','柔和漫射主光从左上方投射，搭配右侧补光消除死黑阴影，瓶身金属盖呈现清晰高光轮廓，整体光线均匀柔化','俯拍45度角，中远景景深全画面清晰，对称式构图','透明红色玻璃瓶（喷雾型×2、按压型×1）、红色玻璃面霜罐、哑光红礼品盒、酒红缎带金边饰、红色细闪粉质底衬','深红、酒红、正红、香槟金、银白、奶油黄（标签）','奢华、节日礼赠、高端美妆、精致、热情、典雅','lainuoniao','素材/参考站AI效果图-715张/66.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','深色香水瓶倚靠在棕色皮革手提包上，背景为柔和的蓝白渐变无缝背景','A luxury deep burgundy perfume bottle with a faceted black gemstone cap resting against a rich brown leather handbag, soft studio lighting from upper left creating delicate specular highlights on the glass and crystal, clean minimal background gradient from pale sky blue to white, close-up product shot with shallow depth of field, 85mm lens, subtle rim light defining the leather edges, high-end commercial beauty photography, ultra-detailed, blank label, 8K quality','奢华深酒红色香水瓶搭配切割水晶瓶盖，倚靠在浓郁棕色皮革手提包上，柔和的左上主光在玻璃与水晶表面形成精致高光，干净的淡天蓝至白色渐变背景，浅景深近景特写，85mm镜头，皮革边缘微弱轮廓光，高端商业美妆摄影，超细节，空白标签，8K画质','柔和漫射主光从左上方打亮瓶身与瓶盖切面，产生精致的高光反射，皮革边缘有微弱轮廓光勾勒，整体光比柔和均匀','近景特写，约85mm焦段，浅景深，相机视角略低于瓶身水平线，微微仰拍突出产品质感','棕色皮革手提包（带缝线细节）、深红色玻璃香水瓶、黑色切割水晶瓶塞、金色金属环、白色渐变背景纸','深酒红、巧克力棕、黑色、金色、淡天蓝、纯白','奢华,优雅,高级感,精致,女性化,时尚,轻奢生活方式','lainuoniao','素材/参考站AI效果图-715张/77.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','高调纯白极简场景，半透明石质平台搭配水珠，背景虚化白色百合花与绿叶，整体空灵纯净','A premium cosmetic jar with a frosted white body and brushed silver metallic lid, centered on a translucent stone disc surrounded by glistening water droplets. Soft white lily petals and delicate green leaves blur gently in the high-key background. Diffused soft main light from above-front creates elegant specular highlights on the metallic lid and subtle rim light around the jar. Shallow depth of field with creamy bokeh, eye-level composition, macro product photography, clean minimal aesthetic, commercial beauty campaign style, crisp sharp focus on the product, soft luminous tones, ethereal and luxurious mood, post-processed for a high-end skincare advertisement.','一只高端化妆品罐，磨砂白色瓶身搭配拉丝银色金属盖，置于半透明石质底座上，周围点缀晶莹水珠。高调纯白背景中，柔和的白色百合花瓣与嫩绿叶片梦幻虚化。上方前侧柔光主光在金属盖上形成优雅镜面高光，罐体边缘有微妙轮廓光。浅景深配合奶油般散景，平视构图，微距商业产品摄影，极简干净美学，美妆大片风格，产品焦点锐利清晰，柔和透亮色调，空灵奢华氛围，后期处理呈现高端护肤广告质感。','高调柔光主光从上方前侧打入，金属盖呈现细腻镜面高光与柔和过渡，罐体边缘有微妙轮廓光，水珠折射亮点，整体光比低、阴影极软','平视微俯角度，浅景深大光圈，背景花朵奶油般虚化，产品主体锐利清晰，微距商业产品摄影视角','磨砂玻璃罐身，拉丝银色金属盖，半透明石质底座，晶莹水珠，白色百合花，嫩绿叶片，水面反光','纯白，银灰，磨砂白，嫩绿，透明水色，点缀红色品牌标识','纯净，水润，奢华，清新，空灵，高端护肤，静谧，透亮','lainuoniao','素材/参考站AI效果图-715张/88.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','纯净粉色渐变背景，从浅粉过渡到蜜桃粉，产品置于白色台面，整体为极简商业棚拍场景','Commercial cosmetic product photography of a matte pink lip color tube with glossy red heart emblem, lined up in receding depth on a pure white surface against a soft pink gradient backdrop. Seven tubes fade into the background creating rhythmic repetition. Soft diffused key light from front-side illuminates the frosted packaging, with white reflector filling shadows. Clean minimal composition with shallow depth of field keeping the front tube sharply in focus while subsequent tubes blur gently. Pastel pink-to-peach color palette throughout. Juicy glossy label design with abstract wave pattern. Studio beauty product shot, high-end commercial aesthetic, soft post-processing with slight color grading for warmth.','商业美妆产品摄影，磨砂粉色唇釉管身搭配亮面红色爱心徽章，排列在纯白台面上，背景为柔和粉色渐变。七支产品由近及远渐隐形成节奏重复。正面偏侧柔光箱主光打亮雾面包装，白色反光板补光填充阴影。极简构图浅景深，前景第一支锐利聚焦，后续产品柔和虚化。蜜桃粉至樱花粉单色系配色，罐身果冻波纹设计。工作室级高端商业美学，柔和后期轻微暖色调色彩分级。','柔光箱主光从正面偏侧45度打亮，搭配白色反光板补光消除阴影，边缘轮廓光勾勒管身立体感，整体光质柔和均匀无硬阴影','平视机位，85mm人像焦段，浅景深虚化后排产品，焦点集中在最前方第一支产品','六支渐隐排列的唇釉管（前后景深递进），白色纯平台面，无其他道具','蜜桃粉、樱花粉、珊瑚粉、草莓红、奶油白，单色系粉调渐变配色','甜美、元气、少女感、清新、浪漫、青春活力、韩系美妆风格','lainuoniao','素材/参考站AI效果图-715张/99.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','阳光明媚的海滩鹅卵石岸边，远处蓝绿色海水轻柔拍打，远处山峦轮廓隐约可见','A luxury white cosmetic tube with a metallic gold cap resting diagonally on smooth white river pebbles at a sunlit beach. A cream silk fabric with delicate gold piping drapes beside it. Warm golden hour backlight creates soft rim highlights on the bottle, with gentle bokeh of turquoise ocean waves and distant rocky cliffs in the background. Shallow depth of field, low-angle macro product photography, commercial beauty aesthetic, blank label, creamy skin-care vibe, softly retouched, high-end editorial finish.','一支奢华白色化妆品管搭配金属金色瓶盖，斜置于阳光照耀的海滩白色鹅卵石上，旁边铺有精致金色滚边的奶油色丝绸织物。暖金色时刻侧逆光在瓶身营造柔和边缘高光，绿松石色海浪与远处岩石悬崖形成柔焦散景。浅景深低角度微距产品摄影，高端美容商业美学，空白标签，柔和修饰，高级编辑级质感。','暖色金色时刻侧逆光从右后方照射，柔和漫反射，金色瓶盖高光边缘光，鹅卵石表面自然反光板补光','低角度微距特写，浅景深虚化背景海浪与远山，产品呈对角线斜置构图','白色光滑鹅卵石、米白色丝绸织物配金色滚边、海洋、远山','金色、象牙白、奶油色、海蓝色、暖米色','奢华、清新、夏日、纯净、优雅、高级感','lainuoniao','素材/参考站AI效果图-715张/109.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('dropper-bottle','手持产品开箱场景，棕色瓦楞纸包装盒置于白色褶皱床单背景上','A hand holding a matte sage-green glass serum bottle with a minimalist off-white label, close-up product photography, soft side window light casting gentle highlights on the frosted glass, kraft cardboard packaging box open in the background with matching jars nestled in molded compartments, crumpled white linen sheet as backdrop, warm natural skin tones, clean earthy palette, shallow depth of field with focus on the bottle label, editorial beauty commercial style, soft post-processing with slight film grain, authentic unboxing aesthetic, no visible branding or text','手持磨砂鼠尾草绿玻璃精华瓶，极简米白标签，侧窗柔光在瓶身形成柔和高光，背景为打开的牛皮纸包装盒，配套面霜罐嵌入模压内托，白色褶皱亚麻床单作背景，温暖肤色，自然大地色系，浅景深聚焦瓶身标签，编辑级商业美容摄影风格，轻微胶片颗粒感后期，真实开箱美学，无品牌标识与文字','侧窗自然柔光为主光，从左上方入射，高光柔和无硬阴影，白色床单充当反光板补光','手持近景视角，约50mm等效焦段，中等景深，略微俯拍，焦点落在瓶身标签','绿色哑光磨砂玻璃精华瓶、米白标签、棕色瓦楞纸分隔包装盒、配套绿色面霜罐、另一支深色瓶装产品、白色床单','鼠尾草绿，米白，浅棕牛皮纸色，奶油白床单，肤色暖调','自然有机，纯净护肤，日常仪式感，简约禅意，开箱分享，Instagram种草风','lainuoniao','素材/参考站AI效果图-715张/120.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','Frosted glass bottle on textured linen with dark wood backdrop','Commercial product photography of a frosted glass bottle filled with pale yellow serum, featuring a sleek black pump and minimalist cream label. The bottle rests on a coarse, textured beige linen fabric, illuminated by strong natural sunlight streaming from the side, creating dramatic shadows and highlighting the translucency of the liquid. Dark wood architectural elements frame the background, providing rich contrast. Shot on a medium format camera, sharp focus, warm and serene aesthetic, high-resolution render.','商业产品摄影，磨砂玻璃瓶内装淡黄色精华，配有简约黑色按压泵头和极简米色标签。瓶子放置在粗糙纹理的米色亚麻布上，受侧面强烈的自然阳光照射，产生戏剧性阴影并突显液体的半透明质感。深色木材建筑元素作为背景，提供丰富的对比度。中画幅相机拍摄，焦点清晰，温暖宁静的审美风格，高分辨率渲染。','Strong directional natural sunlight, high contrast, warm glow','Medium shot, sharp focus, eye-level','Woven beige fabric, dark wooden frame','Pale yellow, cream, beige, deep brown, black','Serene, organic, luxurious, sun-drenched','lainuoniao','素材/参考站AI效果图-715张/121.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','Beauty editorial portrait, woman holding perfume bottle, minimal background','A beauty editorial shot of a radiant woman with dark hair pulled back, holding a rectangular glass perfume bottle near her cheek. She wears a black off-the-shoulder top against a solid sky-blue background. Bright natural sunlight creates a dewy glow on her skin and distinct shadows on her collarbone. The bottle contains pale golden liquid with a minimalist black cap. Clean composition, 85mm lens, commercial fashion photography style, sun-kissed aesthetic.','一幅美容专题照片，画面中一位皮肤光亮的深色头发女性将长方形玻璃香水瓶举在脸颊旁，她身穿黑色露肩上衣，背景为纯天蓝色。明亮的自然阳光在她的湿润肌肤上形成柔和的高光，并在锁骨处投下明显的阴影。香水瓶内盛有淡金色液体和极简黑色瓶盖。构图干净，85mm镜头，商业时尚摄影风格，日晒美学。','Bright natural sunlight, hard directional light, sun-kissed glow, soft shadows','Medium shot, 85mm lens, sharp focus, high definition','Rectangular glass perfume bottle, black cap, pale golden liquid, minimalist white label, black strapless top','Sky blue, warm beige, golden yellow, jet black, crisp white','Fresh, radiant, elegant, summery, confident','lainuoniao','素材/参考站AI效果图-715张/132.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','Six cosmetic lip gloss tubes in gradient shimmer shades arranged diagonally on a clean white surface','Six tubes of shimmering lip gloss in a diagonal arrangement on pure white, each tube revealing suspended glitter in rose, coral, peach, and champagne hues beneath frosted opaque caps, rose gold metallic trim accents, bright softbox studio lighting casting soft directional shadows, top-down angled composition with shallow depth of field highlighting the sparkling texture of the product, professional beauty commercial photography style with high-key illumination and clean minimal backdrop','六支 shimmer 唇釉斜向排列在纯白背景上，每支透明管身展现玫瑰粉、珊瑚、蜜桃和香槟金等色系的悬浮 glitter 质地，磨砂白色管盖搭配玫瑰金金属装饰环，明亮柔光箱从左上角照射形成柔和阴影，俯拍斜角构图带浅景深突出 glitter 闪烁质感，专业美妆商业摄影风格，高调照明与极简背景','Bright studio softbox lighting from upper-left creating defined but gentle shadows, high-key commercial photography setup','Top-down angled shot, shallow depth of field, macro lens detail on glitter texture','White seamless backdrop, six lip gloss tubes in rose gold, coral, peach, and champagne shimmer shades with frosted white caps and clear cylindrical bodies showing suspended glitter particles','Soft blush pinks, warm corals, champagne golds, rose metallic accents, clean white background','Fresh, glamorous, aspirational beauty commercial aesthetic','lainuoniao','素材/参考站AI效果图-715张/143.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','Cosmetic tube close-up with gel bead emerging from nozzle, light mint background','A glossy dark cosmetic tube angled diagonally, with a glistening translucent gel bead emerging from the ribbed nozzle. Soft diffused studio lighting creates subtle specular highlights on the viscous product and smooth tube surface. Clean light mint-green seamless background. Macro photography with shallow depth of field, professional commercial product aesthetic. Minimalist composition emphasizing texture and purity, high-end skincare presentation.','一只光亮的深色化妆品软管对角线倾斜放置，带有光泽的半透明凝胶珠从螺纹喷嘴处挤出。柔和的漫射工作室灯光在粘稠产品和光滑管表面形成微妙的镜面高光。干净的浅薄荷绿无缝背景。微距摄影，浅景深，专业商业产品美学。极简构图强调质地与纯净感，高端护肤品展示风格。','Soft diffused studio lighting, subtle specular highlights on glossy tube and gel surface','Macro lens, shallow depth of field, diagonal composition, commercial product photography','Dark glossy cosmetic tube with ribbed nozzle, translucent gel droplet, dotted circular graphic element','Deep black-green tube, translucent dark gel, light mint background, white accents','Clean, clinical, fresh, professional, luxurious skincare aesthetic','lainuoniao','素材/参考站AI效果图-715张/153.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','深色影棚背景下的美妆唇部产品特写场景','Close-up beauty product photography of a model applying vibrant red lip gloss, clear rectangular plastic tube with high-gloss liquid finish, pale blue geometric cap held in hand with natural nude manicure, studio beauty dish lighting from front-right with soft wrap on face, sharp specular highlights on product surface, deep black background for high contrast, slightly low angle composition, 85mm macro lens, shallow depth of field with selective focus on lips and packaging, crisp detail on cosmetic texture and reflection, high-end commercial retouching, editorial beauty campaign aesthetic, vivid saturated colors, fashion-forward glamorous styling.','近景美妆产品摄影，模特涂抹鲜艳红色唇釉，透明矩形塑料管搭配高光液体质感，手持浅蓝色几何方盖，裸色美甲，影棚 Beauty Dish 前右侧主光伴柔和补光，产品表面锐利高光反射，深黑背景高反差，略低角度构图，85mm 微距镜头，浅景深选择性聚焦嘴唇与包装，细节锐利，高端商业精修，编辑级美妆campaign风格，色彩饱和前卫时尚。','前右侧主光（大型柔光箱/ Beauty Dish）配合硬光质感的 product highlights，面部轮廓柔和过渡，背景深黑形成高反差','近景特写/微距，低角度仰拍，85mm–105mm 镜头，浅景深焦点落在嘴唇与产品上','透明矩形唇釉管（红色液体）、浅蓝色几何方形瓶盖、模特手指（裸色美甲）','深红/莓红色、浅蓝色、暖肤色调、深黑背景','前卫、性感、大胆、高端商业美妆、编辑级时尚感、活力','lainuoniao','素材/参考站AI效果图-715张/164.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','Cosmetic product beauty shot with model','Commercial beauty product photography featuring a frosted cylindrical glass bottle filled with golden facial oil, held elegantly in hand with glass dropper suspended above capturing a glistening amber droplet mid-fall. Dark-skinned model with curly hair slightly blurred in soft-focus background, warm golden-hour lighting creating luminous skin glow and specular highlights on glass surfaces, neutral cream backdrop, 85mm lens for intimate beauty portrait, shallow depth of field isolating product in sharp focus while model face provides warm human context, luxurious skincare aesthetic with rich amber tones complementing golden light, professional cosmetic advertising quality with soft directional key lighting and delicate rim highlights on dropper and bottle edges.','商业美妆产品摄影，磨砂圆柱形玻璃瓶装满金色面部精华油，优雅手持姿态，玻璃滴管悬垂上方捕捉琥珀色油滴即将坠落的瞬间。深色肌肤模特配卷发在柔焦背景中微微虚化，温暖金色时光线营造莹润肌肤光泽与玻璃表面高光，中性米色背景，85mm镜头打造亲密美容肖像，浅景深将产品置于清晰焦点而模特面容提供温暖人文氛围，奢华护肤美学以浓郁琥珀色调呼应金色光线，专业化妆品广告品质，柔和定向主光配合滴管与瓶身边缘精致轮廓高光。','Warm golden natural light, soft directional key, rim highlights','85mm portrait lens, shallow depth of field, close-up framing','Frosted glass bottle, glass dropper, amber facial oil','Warm golds, amber, cream, soft skin tones, neutral background','Luxurious, radiant, warm, inviting skincare moment','lainuoniao','素材/参考站AI效果图-715张/175.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','Light blue pump conditioner bottle on creamy white swirl background with water droplets, minimal product photography','Professional product photography of a light mint-blue pump bottle of conditioner standing on a smooth marble surface, surrounded by swirling creamy white lotion textures with glistening water droplets. The bottle features a sleek black pump dispenser and a clean minimalist label design. Soft diffused studio lighting creates gentle highlights on the glossy bottle surface and creamy background. Shallow depth of field with the main bottle in sharp focus. Luxurious spa-inspired composition with a fresh, premium, clinical-yet-inviting mood. Shot on Canon EOS R5 with 85mm f/1.4 lens, high-end commercial beauty retouching, clean color grading.','专业化妆品产品展示摄影，浅薄荷蓝色按压瓶的护发素置于光滑大理石台面上，周围环绕着乳白色奶油质感的旋涡纹理和晶莹水珠。瓶身配有简约黑色按压泵头和极简风格标签。柔光摄影棚布光在光滑瓶身和奶油背景上形成柔和的高光。浅景深效果，主体清晰锐利。奢华水疗风格的构图，清新高端的医学美学氛围。使用佳能EOS R5配合85mm f/1.4镜头拍摄，高端商业级后期修图，干净的色彩分级。','Soft diffused studio lighting, gentle specular highlights, clean commercial beauty product setup','Medium close-up, eye-level product shot, sharp focus, shallow depth of field','Water droplets, swirling cream texture, marble or glossy surface, pearl accents, white botanical elements','Mint blue, white, cream, soft grey, black accents, pearl white','Clean, luxurious, professional, fresh, premium skincare aesthetic','lainuoniao','素材/参考站AI效果图-715张/186.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','minimalist beauty product setup on geometric blocks','A sleek white cosmetic squeeze tube with a warm-toned cap rests on transparent iridescent geometric blocks against a smooth gradient background fading from deep coral to soft golden peach. Soft warm rim lighting creates a luminous halo around the tube, highlighting its premium matte finish. The vertical composition is centered and clean, shot on an 85mm lens with shallow depth of field for a refined commercial beauty aesthetic. Post-processing enhances the warm glow and subtle color grading amplifies the radiant, rejuvenating mood.','一支精致的白色化妆品软管，配以暖色调瓶盖，置于透明虹彩几何方块上，背景是从深珊瑚色渐变至柔和金黄桃色的光滑渐变背景。温暖的轮廓光在软管周围形成 luminous 光环，凸显其高级哑光质感。垂直构图居中干净，使用85mm镜头以浅景深拍摄，呈现精致的美容商业美学风格。后期处理增强温暖光晕，微妙调色放大明亮焕活氛围。','warm rim light with soft gradient backdrop','85mm lens, shallow depth of field','transparent iridescent acrylic geometric blocks','coral, peach, golden orange, cream, iridescent','luxurious, radiant, warm, premium','lainuoniao','素材/参考站AI效果图-715张/197.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','Product hero shot with hair wrapping','A pristine light blue matte cosmetic squeeze tube stands upright against a stark white background, wrapped elegantly by cascading waves of glossy chestnut brown hair that form an S-curve around the packaging. Soft, diffused studio lighting illuminates the scene from the left, casting a gentle, soft shadow to the right and highlighting the smooth texture of the tube and the shine of the hair. Shot with a medium telephoto lens for a flat, commercial look, the composition emphasizes the product as the central hero, with a clean, high-key aesthetic typical of premium haircare advertising.','一只完美的浅蓝色哑光化妆品软管直立在纯白背景中，被瀑布般的有光泽的栗色波浪卷发优雅地包裹，头发在包装周围形成S形曲线。柔和的漫射工作室灯光从左侧照亮场景，在右侧投下柔和的阴影，突出了管子的光滑质感和头发的光泽。使用中长焦镜头拍摄以获得平面的商业外观，构图将产品作为中心主角，具有典型的高端护发广告的干净高调美学。','Soft studio, diffused, high-key','Medium telephoto, eye-level','Glossy brown hair strands','Sky blue, chestnut brown, white','Hydrating, premium, clean','lainuoniao','素材/参考站AI效果图-715张/208.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','Luxury cosmetic bottle nestled in nautical rope on a yacht deck','Commercial product photography of a sleek white cosmetic dropper bottle with a gold metallic cap and elegant gold foil lettering, nestled securely within a coil of thick, textured white nautical rope on a sun-drenched yacht deck. The background features vibrant turquoise ocean waters and polished silver stainless steel railings with a soft bokeh effect. Bright natural sunlight creates sharp, crisp shadows, emphasizing the matte and gloss textures. Shot on a 50mm lens, high definition, photorealistic 8k render, luxury lifestyle aesthetic.','商业产品摄影，展示一个精致的白色化妆品滴管瓶，配有金色金属盖和优雅的金色烫金字样，安全地放置在船甲板上的一圈厚实的白色航海绳中。背景是鲜艳的绿松石色海洋水和带有柔和散景效果的抛光银色不锈钢栏杆。明亮的自然阳光创造出清晰锐利的阴影，突出了哑光和光泽的质感。使用50mm镜头拍摄，高清，照片级真实8k渲染，奢华生活方式美学。','Bright natural sunlight, high contrast, sharp shadows','50mm lens, eye-level, shallow depth of field','Thick white coiled rope, silver boat railings, turquoise ocean','Crisp white, metallic gold, vibrant turquoise, polished silver','Premium, sunny, refreshing, nautical elegance','lainuoniao','素材/参考站AI效果图-715张/218.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','A dark green cosmetic tube balanced on a stone sphere atop a limestone rock, set against blurred botanical leaves.','A commercial beauty product shot of a dark forest-green matte squeeze tube standing upright on a polished sage-green stone sphere perched on a textured beige limestone rock. The packaging features elegant minimalist botanical line art and clean typography. Soft, diffused natural window light washes over the scene, highlighting the matte finish. Blurred fresh green foliage in the background adds depth. Shallow depth of field, sharp focus on the product, 85mm lens, high-end skincare aesthetic, serene and organic mood, 8k resolution.','一张商业美容产品摄影，画面中是一支深森林绿哑光软管，直立放置在一个抛光的鼠尾草绿石球上，石球又搁置在一块纹理粗糙的米色石灰石岩石上。包装上饰有优雅的极简植物线条艺术和简洁的排版。柔和、漫射的自然窗光洗涤着整个场景，突显出哑光质感。背景中模糊的新鲜绿叶增加了景深。浅景深，焦点清晰地对准产品，85毫米镜头，高端护肤美学，宁静而有机的氛围，8k分辨率。','Soft, diffused natural window light with gentle specular highlights.','Medium close-up, shallow depth of field, sharp focus on the product, 85mm lens aesthetic.','Textured beige limestone slab, polished sage-green sphere, soft-focus green foliage.','Forest green, sage, sandstone beige, crisp white, soft natural tones.','Serene, organic, sophisticated, and clinical.','lainuoniao','素材/参考站AI效果图-715张/229.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('jar','粉色迷你冰箱置于浅色梳妆台面，冰箱门打开，内部散发冷雾蒸汽','Commercial cosmetic product photography, four red and white skincare bottles and two cream jars arranged inside an open pink mini refrigerator sitting on light beige countertop. Products rest on clear crushed ice with fresh glossy red cherries scattered around, subtle cold vapor mist rising. Soft diffused frontal key light with warm white interior fridge light creating clean product illumination. Mid-range 45mm lens, even depth of field keeping all products sharp. Pink pastel background complementing the scene. High-end beauty e-commerce style, color-graded with soft shadows, premium commercial retouch.','商业化妆品产品摄影，四瓶红白配色护肤精华与两罐面霜整齐陈列于打开的粉色迷你冰箱内，置于浅米色梳妆台。产品放置在透明碎冰上，新鲜光泽红樱桃散落其间，冷雾蒸汽微微升腾。正面柔光箱主光配合冰箱内置暖白光，产品照明干净清晰。45mm中焦段镜头，中等景深，所有产品保持锐利。粉色柔和背景呼应场景。高端美妆电商风格，色彩柔和，阴影干净，高级商业修图质感。','柔光箱从正面打光，冰箱内置暖白光顶灯，产品轮廓清晰，反光板补光消除硬阴影','正面平视视角，45mm中焦段，景深中等，冰箱内产品全清晰','樱桃散落在透明碎冰上，粉色迷你复古冰箱，玻璃门，金属铰链','蜜桃粉、酒红、乳白、透明冰晶色、浅米背景','清新、清凉、精致、少女感、高端护肤、夏日降温','lainuoniao','素材/参考站AI效果图-715张/240.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','海边复古粉色美式轿车引擎盖上，白色护栏外是碧蓝海水与棕榈树，晴朗海岸度假场景','A cosmetic stand-up pouch with a blank label, featuring a pale blue gradient top and matte white bottom with a white screw cap, positioned upright on the glossy hood of a vintage pink American car. Bright direct midday sunlight creates hard shadows and vivid specular highlights on the chrome headlight and curved car body. The car is parked near a coastal overlook with a white railing, turquoise ocean, tall palm trees, and a pastel sky with scattered clouds in the background. Shot from a low angle with the rounded headlight prominent in the foreground left for depth. 35mm lens, commercial product photography, vibrant saturated colors, crisp sharp details, retro summer aesthetic, high-end beauty brand style.','一款带有空白标签的化妆品自立袋，上半部为淡蓝渐变、下半部为哑光白色配白色旋盖，直立放置在复古粉红美式轿车的光泽引擎盖上。正午直射日光在镀铬大灯与弧形车身上形成清晰硬阴影和生动镜面高光。车辆停于海岸观景处，白色护栏外是绿松石色大海、高耸棕榈树以及点缀白云的柔和晴空。低角度拍摄，圆形大灯在左前景突出以营造纵深感。35mm镜头，商业产品摄影，色彩鲜艳饱和，细节锐利清晰，复古夏日美学，高端美妆品牌风格。','正午硬日光为主光，从右上方直射形成清晰硬阴影与强烈金属高光，车头镀铬件反射天空，侧逆光勾勒产品轮廓，环境漫反射柔化暗部','低角度侧前方拍摄，35mm定焦，产品居中略偏右置于弧形引擎盖，车头大灯入画作为前景纵深引导，中等景深保留背景棕榈树清晰度','复古粉红美式轿车（1950年代风格）、圆形镀铬大灯、白色金属护栏、棕榈树、蔚蓝海面、远处粉色建筑、晴朗蓝天白云','荧光粉红（车身）、天青蓝（海洋）、晴朗蔚蓝（天空）、纯白（护栏与瓶身标签区）、婴儿蓝（袋体上半）、铬银（车饰件）、翠绿（棕榈叶）','夏日阳光、复古海滨、自由度假、清爽活力、怀旧美式、高端美妆、清新通透、加州风情、愉悦治愈','lainuoniao','素材/参考站AI效果图-715张/241.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','纯米色弧形背景台，干净无杂物，极简静物拍摄环境','Commercial product photography of a tall cylindrical skincare lotion bottle with a matte burgundy cap and cream label featuring gradient red dot pattern, standing center frame surrounded by fresh dewy red apples on a textured beige surface. Hard directional side lighting from upper right creates crisp highlights on apple skin and rim light on the bottle, soft fill shadow to the left. Clean seamless beige cyclorama background. Shot at 85mm, f/5.6, eye-level, shallow depth of field with foreground apples slightly blurred. Natural warm color grading, high-end editorial beauty aesthetic, 8K ultra-detailed, blank label version.','商业产品摄影，高圆柱形护肤乳液瓶，哑光酒红色瓶盖与奶油色标签配渐变红圆点图案，立于画面中央，周围环绕新鲜带水珠的红苹果，置于米色纹理台面上。右侧上方硬光打入，在苹果表面形成清脆高光并在瓶身勾勒出轮廓光，左侧柔和填充阴影。干净无缝米色cyclorama背景。85mm镜头，f/5.6，平视机位，浅景深前景苹果微虚。自然暖色调，高端编辑美容美学，8K超细，空白标签版本。','侧逆光主光从右上方45°打入，硬光质感塑造苹果高光与瓶身轮廓，左侧反光板补暗部，阴影柔和过渡','水平机位平视，85mm定焦，f/5.6中等景深，前后苹果略微虚化，瓶身主体锐利','新鲜红苹果（带水珠）、米色纹理台面、纯色弧形背景布','酒红、奶油白、暖米色、深红、苹果自然红绿渐变','清新自然、有机护肤、高端简约、阳光温暖、健康美容','lainuoniao','素材/参考站AI效果图-715张/251.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','极简纯白影棚背景，纯净无杂物，突出产品主体','Extreme close-up macro shot of a frosted semi-transparent cosmetic gel cream tube, surface covered with glistening condensation water droplets, a delicate gradient leaf illustration in yellow-to-blue tones printed on the front, a single thick gel droplet suspended mid-drip on the right side, soft teal typography on blank label area, gentle left-side key light with soft diffusion wrapping around curves, specular highlights on water beads, clean pure white seamless background, shallow depth of field with soft focus falloff, commercial skincare product photography, high-end beauty aesthetic, crisp detail rendering, 85mm macro lens feel, studio lit with negative fill for subtle contrast','微距特写镜头拍摄磨砂半透明保湿凝胶霜软管，瓶身布满晶莹冷凝水珠，正面印有黄蓝渐变色精致叶片图案，右侧一滴浓缩凝胶悬垂欲滴，柔和深青色字体印于空白标签区域，左侧柔光主光包裹瓶身曲线，水珠表面高光细腻，纯净白色无缝背景，浅景深自然虚化边缘，高端护肤品商业摄影，精致 beauty 美学，超清细节，85mm微距镜头质感，影棚布光保留微妙反差','左侧柔光主光，侧面补光勾勒水珠高光，柔和散射光消除硬阴影，局部轮廓光突出滴落凝胶质感','微距特写机位，中近距离贴拍瓶身，浅景深虚化边缘，平视略仰角','磨砂半透明软管瓶身，渐变叶片图案印花，表面冷凝水珠，滴落凝胶液滴，底部波浪纹装饰线','薄荷绿，雾面白，淡黄渐变，青蓝渐变，深青色字体，水珠透明','清新，水润，自然，纯净，高端护肤，轻盈通透，静谧优雅','lainuoniao','素材/参考站AI效果图-715张/261.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','明亮通透的户外自然场景，白色薄纱窗帘与微距水波纹前景，清晨花园氛围','A serene Asian beauty model with closed eyes, gently tilting her face toward soft morning light, wearing a sheer white blouse, resting her chin on her hand in a relaxed pose. Beside her sits a sleek transparent glass serum bottle with a lavender-colored cap on a reflective water-droplet surface, surrounded by crystal-clear water ripples and glistening droplets. Ethereal white sheer curtains drift in the background with blurred lush green garden foliage beyond. Bright, airy, high-key commercial skincare photography. Soft diffused front-left key light with delicate rim backlight, gentle fill reflecting off a white board. Shot on 85mm lens, shallow depth of field, crisp subject with dreamy bokeh background. Clean minimalist composition with generous negative space for editorial layout. Cool-toned palette of lavender, pearlescent white, and aqua blue. Post-processed with soft contrast, subtle glow, and delicate skin retouching for a fresh dewy luminous finish. High-end cosmetic advertising aesthetic.','一位闭目微仰脸的亚洲模特，身穿白色薄纱上衣，姿态放松恬静，脸颊轻靠手背沐浴在柔和晨光中。身旁摆放着一支透明玻璃精华液瓶身搭配淡紫色瓶盖的护肤品，置于水波纹反光托盘上，晶莹水滴散落四周。背景为飘动的白色薄纱窗帘与虚化的翠绿花园景致。明亮通透的高调商业护肤摄影风格。柔和漫射的前侧主光搭配轻薄轮廓逆光，白色反光板补光。85mm镜头拍摄，浅景深，主体锐利、背景梦幻虚化。留白充足的极简构图，适合平面排版。薰衣草紫、珍珠白与水光蓝的冷调配色。后期低反差柔光处理，肌肤细腻透亮，呈现清新水润的高级美妆广告质感。','柔和漫射晨光从正面偏左侧打入，面部无硬阴影，发丝与肩部有轻薄轮廓逆光，整体低反差柔光质感','中近景人像结合产品特写，85mm定焦视角，浅景深虚化背景，机位略低于模特视线，营造轻盈仰视感','透明玻璃瓶身护肤品、淡紫色瓶盖、水波纹托盘、晶莹水滴、白色薄纱布料、朦胧绿植背景','薰衣草紫、纯净白、水光蓝、柔雾绿、肌肤暖调','清新水润,晨间焕活,温柔治愈,高级简约,轻透空灵,自然纯澈','lainuoniao','素材/参考站AI效果图-715张/271.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','明亮通透的居家窗边场景，白色墙面搭配米色纱帘，背景中有绿植点缀','A hand holding a gradient pink-to-blue cosmetic glass bottle with a clear dome pump cap, golden typography reading blank label, shallow depth of field with a softly blurred female model in the background touching her face near a bright window. Soft natural daylight floods the scene from the right, creating a high-key airy atmosphere. White walls, sheer beige curtains, a potted green plant in the background. Editorial lifestyle product photography, crisp product detail, authentic skin texture, warm and fresh mood, shot on medium telephoto lens, professional beauty commercial aesthetic.','一只手持渐变色粉蓝化妆玻璃瓶，透明圆顶泵头盖，金色字体标注blank label，浅景深，背景中女性模特轻触脸庞位于明亮窗边。柔和自然日光从右侧洒入，营造高调通透氛围。白色墙面、米色纱帘、背景绿植盆栽。编辑式生活方式产品摄影，产品细节锐利，肌肤质感真实，清新温暖情绪，中焦镜头拍摄，专业美妆商业美学。','右侧窗户自然光为主光，柔和漫射光质，无明显阴影，整体高亮调，辅以白色墙面反光板补光','手持特写视角，中近景焦段，产品前景清晰锐利，人物面部与背景适度虚化，浅景深突出主体','粉色渐变蓝色玻璃化妆瓶、透明圆顶泵头盖、绿植盆栽、白色花盆、米色窗帘','渐变粉蓝、金色字体、肤色、纯白、米色、绿植翠绿','清新自然、轻松愉悦、日常美感、透明质感、阳光氛围、女性自信','lainuoniao','素材/参考站AI效果图-715张/281.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','纯白无缝背景，一只肤色偏深的手托举着方形深色香水瓶，手腕处露出白色毛绒袖口与金属纽扣细节，极简高级商业摄影场景','A hand gently holding a luxury perfume bottle against a pristine white seamless background. Square deep navy glass bottle with a high-gloss black cap and a blank label. Soft diffused studio lighting from the front creates elegant specular reflections on the glass surface. The wrist reveals a cozy white fuzzy sleeve cuff with a silver metallic button detail. Manicured nails with subtle decorative accents add refinement. Shot on medium-format camera with a 50mm lens, eye-level perspective, shallow depth of field keeping the bottle in sharp focus while softly framing the hand. Minimalist high-end cosmetic product photography, clean composition, polished post-processing with subtle contrast enhancement.','一只手优雅地托着一瓶奢华香水，置于纯白无缝背景前。方形深海军蓝玻璃瓶身搭配亮黑色瓶盖，标签留白。正面柔光箱照明在玻璃表面形成精致镜面高光。手腕处露出白色毛绒袖口与银色金属纽扣细节，精致美甲增添细腻质感。中画幅相机50mm镜头平视拍摄，浅景深突出香水瓶主体，柔和构图的商业级化妆品质感照片，极简构图，后期微对比度强化。','正面柔光箱主光均匀打亮瓶身，玻璃表面有细腻镜面高光反射，无硬阴影，辅以微弱轮廓光勾勒瓶肩边缘，整体光比柔和干净','正面平视视角，略俯拍，中焦段（约50mm等效），浅景深确保香水瓶锐利清晰，主体居中构图','深色方形玻璃香水瓶、黑色亮面瓶盖、手部、白色毛绒袖口、银色圆形金属纽扣、装饰美甲','深海军蓝、纯白、亮黑色、暖肤色、金属银、指尖裸粉点缀红色心形','奢华、优雅、静谧、极简、高级感、精致、温柔、现代','lainuoniao','素材/参考站AI效果图-715张/291.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','米色亚麻布面台面，背景为暖调米色墙面，午后阳光斜照形成柔和阴影','A premium cosmetic pump bottle in soft lavender and deep purple tones, blank label with elegant floral graphic design, sitting on a natural beige linen fabric surface. Fresh purple cornflowers and closed pink flower buds scattered nearby. Warm afternoon sunlight streams from the left, casting soft shadows on a creamy off-white wall behind. Clean minimal composition, lifestyle product photography style, subtle bokeh in the background, natural botanical aesthetic, high-end spa product shoot, soft diffused lighting with gentle contrast, photorealistic commercial render, 85mm lens look','高端美容按压瓶，柔和薰衣草紫与深紫色调，空白标签配优雅花卉图形设计，置于天然米色亚麻布面上。新鲜紫色矢车菊与粉色含苞花蕾散落周围。午后暖阳从左侧倾泻，在奶油色白墙背景上投下柔和阴影。干净极简构图，生活方式产品摄影风格，背景轻微虚化，天然植物美学，高端SPA产品拍摄，柔和漫射光搭配温和明暗对比，写实商业渲染，85mm镜头质感','左侧暖调自然光主光，柔和漫射，墙面投射清晰轮廓阴影，无硬光反差','平视机位，中近景拍摄，轻微浅景深，背景自然虚化','新鲜紫色矢车菊、粉色含苞花蕾、米色亚麻布料、自然光影','淡薰衣草紫、深紫色、奶油米色、象牙白、柔粉色、暖驼色','宁静放松、天然有机、高端SPA感、植物系美学、温柔治愈','lainuoniao','素材/参考站AI效果图-715张/301.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','纯色无缝背景上的静物摄影场景，极简干净的商业摄影棚布置','A premium skincare essence bottle with soft pink-coral liquid and condensation droplets on the surface, tall cylindrical shape with a matte white cap, standing upright beside a whole orange, a freshly cut orange half stacked on top, and a small orange wedge. A sprig of green botanical herb rests near the base. Seamless off-white backdrop, bright diffused studio lighting with soft shadows, clean minimalist flat-lay composition, shot on 85mm lens, commercial product photography style, ultra-sharp details, soft pastel color grading, fresh and airy mood.','一瓶带有蜜桃粉橙色调精华液的 premium 护肤产品，瓶身凝结水珠，圆柱形瓶身搭配哑光白盖，旁边摆放完整橙子、切开的半颗橙子叠放、一小块橙角，底部点缀绿色香草枝叶，无缝奶油白背景，明亮柔光摄影棚布光带柔和阴影，极简扁平化构图，85mm 镜头拍摄，商业产品摄影风格，超清晰细节，柔和粉彩色调，清新通透氛围','正面柔和主光配合侧面补光，漫射光质，瓶身有水珠高光，反光板柔化阴影，无硬阴影','平视角度/中焦段（约85mm）/全场景清晰景深/三分法构图','新鲜橙子、切开的半颗橙子、橙角片、绿色香草枝叶、透明冷凝水珠','蜜桃粉橙色、奶油白、鲜亮橙黄、翠绿、柔和米白背景','清新自然、纯净有机、高端护肤、明亮通透、法式极简、活力水润','lainuoniao','素材/参考站AI效果图-715张/311.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','纯白简约演播室背景，产品置于白色圆形展示台，干净无杂物','A matte pink cosmetic jar with a clean white lid centered on a white circular display platform, surrounded by fresh ripe strawberries and vibrant green leaves, small spills of pink product liquid pooling on the surface. Soft diffused daylight from upper left casting a sharp diagonal shadow, white bounce fill eliminates harsh shadows. Clean all-white studio background. Eye-level frontal composition, 85mm lens, sharp focus throughout. High-end commercial beauty product photography, minimal aesthetic, soft pastel palette, HDR retouching, advertising-grade polish.','哑光粉色美妆罐配纯白平滑罐盖，居中置于白色圆形展示台，周围环绕新鲜饱满草莓与翠绿叶片，粉色产品液滴轻洒台面。左上方柔和散射日光投射清晰对角线投影，白色反光板消除硬阴影，纯白演播室背景干净无杂物。平视正面构图，85mm镜头，全场景锐利聚焦。高端商业美妆摄影，极简美学，柔和粉彩配色，HDR精修，广告级质感。','左上方主光投射柔和大面积散射日光，右侧反光板补光消除阴影，右上方可见清晰对角线投影勾勒立体轮廓','平视90°正面机位，85mm焦段，小光圈f/11保证整体清晰，景深适中前后景皆锐利','粉色圆柱乳霜罐、白色平滑罐盖、鲜红草莓、翠绿草莓叶、粉色产品液滴、白色圆形展台','柔粉色罐身、纯白背景与盖子、鲜红草莓、翠绿叶片、淡粉液滴点缀','清新自然、纯净美妆、极简高级、阳光活力、健康有机、商业质感','lainuoniao','素材/参考站AI效果图-715张/321.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','纯白极简背景搭配失焦的柔和球形光斑，置于白色几何展台上','Frosted glass dropper serum bottle with black matte dropper cap, rectangular body with soft rounded edges, warm peach-orange square label with clean typography, placed on a pristine white geometric pedestal. Soft diffused studio lighting from front-left creating gentle highlights and subtle rim glow on the glass edges. Minimalist white backdrop with out-of-focus soft peach spherical bokeh forms floating in background. Eye-level composition with shallow depth of field, 85mm lens, tack-sharp focus on the bottle with creamy blurred background orbs. High-end commercial skincare aesthetic, clean retouched finish, soft shadow rendering.','磨砂玻璃滴管精华瓶，搭配哑光黑色滴管盖，方形瓶身带柔和圆角，温暖的桃橙色方形标签配简洁排版，置于纯白几何展台上。左前侧柔光箱主光产生温润高光与玻璃边缘微妙轮廓光。极简白色背景，背景中漂浮着失焦的柔和桃色球形散景。正面平视构图，浅景深，85mm镜头，瓶身锐利聚焦，背景光斑奶油般柔化。高端商业护肤美学，干净精修质感，柔和阴影渲染。','柔光箱主光从左前侧照射，产生温润漫反射高光，边缘辅以微弱轮廓光，反光板填充暗部','正面平视机位，85mm焦段，浅景深聚焦瓶身，背景光斑呈柔化散景','磨砂玻璃滴管瓶、黑色滴管盖、白色几何展台、失焦半透明球体','象牙白、柔桃粉、暖杏橙、哑光黑、米白','纯净、高级、极简、科学护肤、温暖、专业','lainuoniao','素材/参考站AI效果图-715张/332.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','深蓝色细腻纹理背景上的垂直切口造型，产品嵌入其中','A luxury cosmetic product photography shot featuring a sleek gradient blue glass bottle with a sharp black tapered cap, emerging vertically from a custom-cut slit in a deep navy blue textured leather background. Studio lighting with soft rim light highlighting the bottle silhouette and material texture. Clean composition, high-end skincare aesthetic, sharp focus, commercial quality, 8k resolution.','奢华化妆品摄影作品，展示一瓶精致的渐变蓝玻璃瓶，配有尖锐的黑色锥形瓶盖，垂直从深海军蓝纹理皮革背景的定制切口裂缝中显露。工作室布光，柔和的轮廓光勾勒出瓶身剪影和材质细节。构图干净，高端护肤美学，焦点锐利，商业级品质，8k分辨率。','侧前方柔光主光，轮廓光勾勒瓶身线条，底部微反光板补光，突出皮革质感与玻璃光泽','平视正面机位，微距镜头，景深适中，焦点清晰锐利','深蓝色仿皮纹理背景板、金属质感切口边框、蓝色渐变玻璃瓶','深海蓝、皇家蓝、黑色、银色文字','奢华、高端护肤、科技感、精致、神秘、专业','lainuoniao','素材/参考站AI效果图-715张/342.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('tube','渐变暖金色背景，左侧明亮右侧深邃暗调，营造出奢华香水广告的高级氛围','Luxury perfume bottle with amber-colored liquid, rectangular glass vessel with thick crystal-clear base and polished gold metallic cap, centered composition against a dramatic warm gradient background transitioning from bright golden yellow to deep shadow, strong side lighting from the left creating a luminous glow along the bottle edge and casting a soft dark shadow to the right, shallow depth of field with the bottle in sharp focus, minimal dark reflective surface beneath, rich golden color grading, high-end commercial beauty photography, studio quality, blank label, ultra-detailed, 8k resolution','奢华香水瓶，琥珀色液体，矩形玻璃瓶身配光滑金色金属瓶盖，居中构图，背景为戏剧性暖渐变，从明亮的金黄色过渡到深邃暗影，左侧强侧光沿瓶身边缘形成发光效果并在右侧投下柔和阴影，浅景深使瓶身清晰对焦，底部为极简黑色反光台面，浓郁金色调色彩分级，高端商业美妆摄影，影棚品质，空白标签，超精细，8k分辨率','强侧光从左方45°入射，硬调主光勾勒瓶身轮廓，右侧投影深邃，背景渐变过渡自然，无额外反光板','平视机位，50mm标准焦段，浅景深虚化背景，正侧面角度完整展示瓶身形态','琥珀色香水瓶，金色金属瓶盖，黑色哑光台面','琥珀金,深红,暖黄,漆黑,香槟金','奢华,温暖,优雅,神秘,高端,精致','lainuoniao','素材/参考站AI效果图-715张/360.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','深色极简影棚环境，产品斜置于奶油色毛绒织物表面，自然戏剧化光影氛围','A blank-label luxury lip tint tube and matching rectangular box arranged diagonally on a creamy white faux fur textile. Single hard directional light from upper right cuts a dramatic wedge of warm brightness across the scene, leaving deep chocolate-brown shadows in the lower left. Soft focus on the product with gentle bokeh in the background. Shot from a 45-degree high angle with a 50mm lens, shallow depth of field isolating the cylindrical tube and matte-finish packaging. Warm terracotta and cream color story with a thin gold accent line. Moody, cinematic commercial beauty photography, editorial aesthetic, rich tonal contrast, softly grainy film-like post-processing.','空白标签奢华唇彩软管与配套长方体纸盒斜置于奶油白仿皮草织物上。单侧硬光从右上切入，形成戏剧性楔形亮区，左下保留深巧克力色阴影。产品主体清晰、背景柔和虚化。45度俯视机位，50mm镜头，浅景深突出圆柱软管与哑光包装。暖陶土色与奶油白配色，金色细线点缀。情绪化电影感商业美妆摄影，editorial美学，浓郁色调对比，轻柔胶片颗粒后期。','单侧硬光从右上方向入射，形成楔形亮区与浓重对角阴影，产品边缘有金色反光勾勒，无反光板补光，保留暗部情绪','俯视约45度机位，中焦段(50-85mm等效)，浅景深对焦于产品主体，背景柔和虚化','哑光棕色唇彩软管、配套长方体纸盒包装、奶油白仿皮草或羊毛质感织物','暖棕陶土色、奶油白、深褐暗影、金色细线点缀','温暖、私密、奢华、电影感、情绪化、秋冬氛围、高级美妆 editorial','lainuoniao','素材/参考站AI效果图-715张/362.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','纯白无缝背景，极简摄影棚环境，带有柔和投影的漫反射空间','A high-end matte black cylindrical perfume bottle featuring a clean white label with sophisticated serif typography. The bottle is positioned at a dynamic tilt on a smooth reflective surface. Soft, diffused key light illuminates the scene from the upper left, casting gentle, artistic shadows against a pristine white seamless background. Shallow depth of field renders the reflection blurry and dreamy. Shot on 85mm lens, commercial beauty photography, 8k resolution, hyper-realistic textures, elegant and minimalist aesthetic.','一款高端哑光黑色圆柱形香水瓶，配有简洁的白色标签和精致的衬线字体。香水瓶以动态倾斜的角度放置在光滑的反光表面上。柔和的漫射主光从左上方照亮场景，在完美的白色无缝背景上投下温和的艺术阴影。浅景深使倒影显得模糊而梦幻。使用85mm镜头拍摄，商业美容摄影，8k分辨率，超写实纹理，优雅极简的美学风格。','柔和的漫射主光从左上方照射，搭配轮廓光勾勒瓶身边缘，背景有形状柔和的投影，整体高光质感，避免硬阴影','微距视角，略低机位，浅景深，前景有模糊的反射倒影，主体清晰锐利','黑色哑光香水瓶，白色标签，反光桌面，模糊的有机形态遮挡物','黑白灰，哑光黑，珍珠白，银色光泽，极简单色调','奢华，优雅，静谧，极简主义，高端，现代感','lainuoniao','素材/参考站AI效果图-715张/372.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','黑色纯底背景下，白色网兜（足球球网样式）兜住一只化妆品瓶','A commercial product photography shot of a cream-colored cosmetic bottle with a cracked ceramic glaze texture, caught and suspended inside a white sports-style mesh net against a pure black background. The bottle features a blank label with elegant serif typography in brown. Dramatic studio lighting from the upper left creates strong contrast, soft shadows, and subtle rim light defining the contours of the bottle and net fibers. Top-down angled composition with shallow depth of field keeping the bottle sharply in focus while the net background softly blurs. Minimalist high-contrast aesthetic with a luxury beauty campaign feel.','商业产品摄影：一只米白色化妆品瓶，表面带有裂纹釉面质感，被白色运动网兜兜住悬浮于纯黑背景前。瓶身带有空白标签和优雅的棕色衬线字体。左上方戏剧性摄影棚布光营造强烈明暗对比，柔和阴影与微妙的轮廓光勾勒出瓶身与网绳的形态。俯视斜角构图，浅景深聚焦瓶身主体，背景网眼自然虚化。极简主义高对比美学，奢华美妆广告大片质感。','主光从左上方打亮，硬柔结合，边缘有轻微轮廓光勾勒瓶身与网绳，黑色背景形成强烈明暗对比','俯视略带斜角，浅景深聚焦瓶身主体，背景网眼自然虚化','化妆品瓶（裂纹釉面质感）、白色尼龙网兜、纯黑背景布','纯白、米白、深棕文字、纯黑','高级感,极简主义,戏剧张力,时尚大片,静物艺术,黑白对比','lainuoniao','素材/参考站AI效果图-715张/382.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','明亮的室内环境，窗边自然光氛围，前景与背景均有模糊的粉色花卉装饰','Commercial beauty photography, a beautiful young Asian woman with natural makeup holding a pink lipstick tube gently against her lips, soft dreamy expression, wearing a sheer white blouse. Bright airy indoor setting with soft morning window light flooding the scene, creating an ethereal high-key glow. Foreground and background feature blurred pink roses and flowers creating a romantic bokeh effect. Shallow depth of field, 85mm lens aesthetic, clean and fresh composition. Soft pastel color palette, flawless skin texture, pure and innocent atmosphere, high-end cosmetic advertisement style.','商业美容摄影，一位妆容自然的年轻亚洲女性，将粉色唇膏管轻抵唇边，表情梦幻温柔，身穿白色薄纱衬衫。明亮的室内环境，柔和的晨间窗光洒满场景，营造出空灵的高调光泽。前景和背景有模糊的粉色玫瑰花，形成浪漫的散景效果。浅景深，85mm镜头美学，干净清新的构图。柔和的粉彩色调，无瑕的肤质，纯净无辜的氛围，高端化妆品广告风格。','柔和的侧逆自然光（窗光），高调照明，发丝轮廓光，整体光线漫射无硬阴影','平视视角，中景镜头，浅景深，背景与前景花卉呈现梦幻散景效果','粉色玫瑰/鲜花，粉色马克杯，粉色唇膏管，白色纱质衣物','柔粉色，奶油白，浅杏色，暖棕色，淡米色','浪漫，清新，梦幻，纯欲，自然妆感，温柔，少女感','lainuoniao','素材/参考站AI效果图-715张/392.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','清新绿色调场景，猕猴桃与青柠元素环绕悬浮于金色护肤罐周围，背景为柔和虚化的绿色马赛克方格图案','A premium cosmetic jar with frosted gold glass body and ornate embossed metallic cap, floating diagonally amidst two dew-kissed kiwi fruits, lime slices, curled citrus peel ribbons, and fresh green leaves. Soft studio lighting with directional key light creating smooth specular highlights on the jar surface and delicate rim light outlining edges. Background features a softly blurred green geometric mosaic tile pattern. Shallow depth of field isolates the product. Vibrant color grading with rich greens and warm golds. Commercial beauty product photography style, aspirational botanical skincare aesthetic, food-grade prop styling, ultra-detailed, 8K resolution.','一款高端护肤品罐，磨砂金色玻璃罐身搭配精致浮雕金属盖，斜向悬浮于两颗带着水珠的猕猴桃、青柠切片、卷曲的柑橘皮丝和新鲜绿叶之间。柔光位主光在罐身形成细腻高光渐变，边缘勾勒柔和轮廓光。背景为柔和虚化的绿色几何马赛克方格图案。浅景深突出产品主体。色彩浓郁鲜活，绿色与暖金色调和谐交融。商业美妆产品摄影风格，植物萃取护肤美学，精致道具布置，超高清细节，8K分辨率。','柔光位主光从侧前方打来，金属罐身呈现细腻的高光渐变与轮廓光，水果表面水珠反光清晰，整体光质柔和且富有层次','中近景产品视角，约85mm焦段，浅景深虚化背景方格，罐体呈斜向悬浮构图，动态漂浮感','金色玻璃/塑料护肤罐（浮雕花纹盖）、带水珠猕猴桃、青柠切片、青柠皮卷丝、绿色嫩叶枝条','金绿色、琥珀金色、翠绿、青柠黄、深棕猕猴桃皮色','清新自然、奢华精致、活力生机、高端护肤、自然植萃、清新疗愈','lainuoniao','素材/参考站AI效果图-715张/402.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','深蓝色水面背景，香水瓶置于透明冰块堆上，环绕天然植物与水果元素','Premium cosmetic product photography of a square glass perfume bottle with black cap, sitting on clear ice cubes in shallow blue water. Lemon slice, lavender sprigs, and evergreen foliage arranged artistically around the bottle. Cool blue cinematic lighting with strong rim light on the glass edges, refraction through ice crystals. Shot from slightly elevated angle with shallow depth of field, macro lens detail. Ripples in dark blue water, luxurious aquatic atmosphere. Studio product render, high-end commercial aesthetic, professional retouching.','高端化妆品商业摄影，方形玻璃香水瓶配黑色瓶盖，置于浅蓝色水中的透明冰块上。柠檬切片、薰衣草枝条和柏树枝叶在瓶周围艺术陈列。冷调电影光，玻璃边缘强烈的轮廓光，冰晶折射效果。略高的俯拍角度，浅景深，微距镜头细节。深色蓝色水面波纹，奢华水生氛围。工作室产品渲染，高端商业美学，专业后期修图。','主光来自左上方，冷调硬光塑造冰晶折射与玻璃边缘轮廓光，右侧柔光板补光，整体蓝光氛围','中近景俯拍，微距镜头，浅景深突出主体，45度角视角','透明冰块，黄柠檬切片，薰衣草枝条，柏树枝叶，深蓝色水面，方形玻璃香水瓶，黑色瓶盖','深海蓝，冰蓝，青绿，明黄，薰衣草紫，黑色','奢华，清新，高端，冷静，优雅， aquatic氛围','lainuoniao','素材/参考站AI效果图-715张/412.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','温馨咖啡馆室内场景，木质桌面，柔和暖调环境','Elegant Asian woman applying deep burgundy lipstick in a warm café setting, soft golden hour lighting from front-left, rim light on hair strands, shallow depth of field with bokeh background lights. She wears a brown turtleneck, holding a metallic-finish lipstick tube with blank label. A matching lipstick stands upright on the wooden table beside a white coffee cup, leather notebook, and silver pen. Circular inset close-up reveals the smooth lipstick bullet texture. Cinematic color grading, warm tone palette, high-end beauty commercial style, photorealistic, 85mm lens, professional studio product photography meets lifestyle portrait.','优雅亚洲女性在温馨咖啡馆涂抹深酒红色口红，左前方柔光主光，发丝边缘轮廓光，浅景深虚化背景光斑。身穿棕色高领毛衣，手持金属质感口红管（空白标签）。桌上直立摆放同款口红、白色咖啡杯、皮质笔记本与金属笔。圆形细节图展示丝滑膏体质感。电影级调色，暖色调，高端美妆商业摄影风格，写实，85mm镜头，专业产品摄影与生活方式人像结合。','主光来自左前方柔光箱，面部轮廓光勾勒发丝边缘，桌面反光板补光，背景散景光斑点缀','中近景人像视角，85mm镜头，浅景深虚化背景，焦点锁定面部与唇部','金属管身口红、白色咖啡杯碟、皮质笔记本、金属笔、圆形产品细节放大圈','深酒红、暖棕色、米白色、金色暖调、柔和深褐','优雅精致、自信从容、丝滑质感、都市女性、高端美妆','lainuoniao','素材/参考站AI效果图-715张/422.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','窗台边自然光下的亚麻布景，清新治愈的护肤产品展示环境','Professional cosmetic product photography of an amber gradient glass essence bottle with wooden dropper cap, lying on textured beige linen fabric alongside fresh lemon slices, mint leaves, and clear ice cubes. Soft natural window light from the left creates warm golden hour glow, highlighting the bottle''s transparency and liquid color. Sheer white curtains in the background add depth. Shallow depth of field with bokeh effect. High-end skincare commercial style, clean composition, 8k resolution, photorealistic,细腻质感','专业化妆品广告摄影，琥珀色渐变玻璃精华瓶配木质滴管盖，置于米色褶皱亚麻布上，周围点缀新鲜柠檬切片、薄荷叶与透明冰块。左侧柔和自然窗光营造温暖黄金时刻光感，突出瓶身透明度与液体色泽。背景白色薄纱窗帘增加空间层次。浅景深虚化效果，高端护肤商业风格，构图干净，8k分辨率，照片级真实质感','左侧柔和窗光为主光，自然漫反射形成柔光效果，搭配反光板提亮暗部，营造温暖通透的轮廓光','低角度平视拍摄，50mm定焦镜头，中等景深突出主体，背景窗帘虚化','琥珀色渐变玻璃精华瓶、木质滴管盖、新鲜柠檬切片、薄荷叶、透明冰块、镂空蕾丝布、褶皱亚麻布','暖金棕色,柠檬黄,亚麻米色,薄荷绿,透明冰蓝,柔和白色','自然纯净,高端护肤,清新活力,阳光治愈,质感细腻,夏日清爽','lainuoniao','素材/参考站AI效果图-715张/432.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','柔和干净的浅米色商业静物场景，产品置于天然石板上，周围散落水珠与干花点缀','A luxury skincare serum bottle with speckled white glass body and metallic silver dropper cap, placed centrally on a textured natural stone slab with scattered water droplets. Soft dried flowers and botanical elements blur gently in the background against a warm neutral beige studio setting. Soft diffused key light from above and front, subtle specular highlights on the glass and metal surfaces, clean commercial beauty lighting with minimal shadows. Shot from a slightly elevated three-quarter angle, 50mm lens, shallow depth of field, premium editorial aesthetic with spa-like minimalism and scientific elegance.','一瓶奢华护肤精华，磨砂白点纹理玻璃瓶身搭配银色金属滴管盖，居中置于纹理天然石板上，周围散落晶莹水珠。背景为柔和虚化的干花与植物元素，暖米色商业静物棚景。顶部前方柔光箱散射主光，玻璃与金属表面呈现细腻高光，干净的商业美妆布光，阴影极简。微俯三分之二维拍摄，50mm镜头，浅景深效果，高端杂志级质感，融合水疗极简风格与科学护肤美学。','主光为顶部柔光箱散射光，前方反光板补光，玻璃滴管与金属盖呈现清晰高光与边缘轮廓光，整体光线均匀柔和无硬阴影','微俯视角（约30度），中近景构图，50mm定焦镜头，浅景深使背景花卉柔焦虚化','纹理石板、透明玻璃滴管瓶、银色金属盖、水珠、干花、分子结构图元素、品牌标识贴纸','米白、浅灰、银白、淡金、透明玻璃色、矿物灰','高端、洁净、科学护肤、温和奢华、极简主义、spa感、专业可信','lainuoniao','素材/参考站AI效果图-715张/442.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','阳光透过窗户洒在灰白色墙面上形成斑驳叶影，石质托盘置于玻璃桌面上','Commercial skincare product photography. A sleek white pump bottle with blank label sits on a round travertine stone tray beside a glass candle and an amber wooden comb. A person''s hands gently apply cream above, captured mid-motion. Soft dappled leaf shadows dance across a warm grey wall from directional sunlight streaming through a window. Glass-top white table with minimalist aesthetic. Natural hard light with subtle fill reflection, crisp shadows, editorial composition. Shot at eye-level slight high angle, 50mm lens, clean neutral palette of cream off-white and warm grey tones. Calm, serene, high-end spa atmosphere.','高端护肤产品商业摄影。一只优雅的白色按压泵瓶（空白标签）置于圆形 travertine 石质托盘上，旁边搭配玻璃蜡烛和琥珀木梳。人物双手正在上方轻柔涂抹护手霜，捕捉动态瞬间。温暖灰墙面上投射着窗户透入的斑驳叶形光影。玻璃台面白色极简桌。自然硬光搭配柔和补光，阴影清晰，编辑级构图。平视略带俯视角度，50mm镜头，奶油白与暖灰纯净色调。宁静治愈，高端水疗氛围。','侧逆自然窗光为主光，硬光质感，墙面投射清晰叶形阴影，前方反光板柔化暗部，轮廓光勾勒手部边缘','平视略俯视角，中焦段约50mm，景深适中，前景手部与产品均清晰，浅景深虚化背景墙','白色按压泵瓶(blank label)、圆形 travertine 石质托盘、透明玻璃蜡烛杯、橙色木质梳子、玻璃桌面、白色金属桌架','米白、奶油色、暖灰、黑色、琥珀木色、透明玻璃','极简主义、宁静治愈、编辑级质感、自然光感、高端护肤、日系禅意','lainuoniao','素材/参考站AI效果图-715张/452.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','淡蓝色天空与轻柔白云，清新通透的户外氛围','A white sunscreen spray bottle with a light blue pump and base, floating diagonally against a soft pale blue sky with wispy white clouds. The nozzle is actively spraying a fine luminous mist upward, catching the light. Matte white cylindrical canister with orange SPF typography. Soft diffused natural key light from upper left, gentle fill, clean highlights on the bottle curve, subtle rim light on the spray particles. Low-angle仰 shot, 35mm lens, moderate depth of field, minimalist commercial product photography, bright airy summer mood, high-end beauty ad aesthetic.','一瓶白色防晒喷雾，浅蓝色喷头与底盖，对角线悬浮于淡蓝天空与轻柔白云背景前。喷嘴正喷出细腻明亮的雾状水雾。哑光白色圆柱罐体搭配橙色SPF标识。柔和漫射自然主光从左上方照射，填充光干净，瓶身高光柔和，喷雾颗粒边缘微勾轮廓光。低角度仰拍，35mm镜头，中等景深，极简商业产品摄影，明亮轻盈夏日氛围，高端美妆广告质感。','柔和漫射主光从左上方照射，瓶身高光清晰，喷出的雾状喷雾被边缘光勾勒，配合反光板填充阴影，整体光质明亮柔和','低角度仰拍视角，约35mm焦段，对角线构图，产品居中悬浮，景深适中背景云朵略虚化','防晒喷雾瓶（白色磨砂罐体、浅蓝色喷头与底盖）、细腻水雾喷雾、淡蓝天空白云背景','天空蓝、纯白、浅蓝色、橙色文字点缀','清新、轻盈、透亮、专业商业、夏日感、洁净','lainuoniao','素材/参考站AI效果图-715张/470.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('pump-bottle','金色沙滩与水沫交织的夏日海滨平面场景','Top-down flat-lay commercial product photography of a bronze metallic body shimmer oil bottle with a white cap, lying diagonally on wet golden beach sand surrounded by swirling sea foam and delicate water ripples. Crystal-clear water droplets glisten on the reflective bottle surface, catching bright directional sunlight that casts a sharp soft-edged shadow. Warm golden-hour ambient light, high-end cosmetic aesthetic, crisp fine sand texture visible, minimalist composition with organic foam framing, shot on medium format digital camera, 50mm lens, sharp focus throughout, studio-quality retouching, lifestyle beauty editorial style, no text or branding, blank label surface','正俯视平面构图商业产品摄影，一款古铜金属质感身体闪光油瓶配白色瓶盖，斜置于湿润金色沙滩上，四周环绕漩涡状海浪泡沫与细腻水纹。瓶身凝结晶莹水珠，明亮侧顶日光投射出清晰柔和阴影，暖金色时段氛围光，高端美妆视觉风格，精细沙粒质感清晰可见，有机泡沫构图框景，中画幅数字相机拍摄，50mm镜头，全域锐利对焦，影级后期精修，生活方式美妆大片风格，无文字无品牌，空白标签表面','明亮侧顶日光，硬调主光塑造清晰投影，反光板补亮瓶身金属质感，自然轮廓光勾勒水珠边缘','正俯视（flat-lay），中焦段约50mm，全景点景清晰呈现沙粒与泡沫细节','湿沙、白色泡沫、透明水珠、浅水涟漪、金色细沙','暖金棕、铜棕色、奶油白、沙米色、透明水光','夏日度假、奢华护肤、阳光闪耀、清新滋润、海滩风情、高端美妆','lainuoniao','素材/参考站AI效果图-715张/480.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','日落时分的海边，人物剪影手持瓶身，远山与海面上有船影，金色夕阳沉于地平线','A human silhouette hand holding a translucent cylindrical bottle filled with amber liquid against a stunning golden sunset over the ocean, the sun dipping low on the horizon with a distant mountain range and a faint ship silhouette on the water. Strong backlighting creates a dramatic rim glow around the bottle while the figure remains in deep shadow. Warm amber and orange tones permeate the sky and are reflected through the liquid inside the bottle. Shot with a medium-length lens, eye-level composition, shallow depth of field keeping the bottle in sharp focus while the seascape softly blurs into the background. Commercial product photography, cinematic color grading, elegant lifestyle aesthetic, soft post-processing with enhanced warmth and golden hour saturation.','一只人物剪影的手持握着一只装满琥珀色液体的半透明圆柱形瓶身，背景是金色的日落海景，太阳贴近地平线，远山轮廓与海面上一艘隐约的船只。强逆光在瓶身周围形成戏剧性的轮廓光，人物保持深剪影效果。温暖的琥珀色与橙色充盈天空，透过瓶内液体反射。中焦段镜头拍摄，平视构图，浅景深确保瓶身锐利清晰，远景柔和虚化过渡。商业产品摄影风格，电影级色彩分级，优雅的生活方式美学，后期增强暖调与黄金时刻饱和度。','强逆光主光来自低角度落日，人物呈剪影，瓶身被暖光穿透产生边缘轮廓光，远处海面有柔和反光','中景平视机位，镜头略仰角，浅景深突出瓶身主体，背景落日与山峦柔焦过渡','半透明圆柱形瓶身、琥珀色液体、人物剪影手部、远海、远山剪影、船只剪影、波光水面','琥珀金、落日橙、深褐剪影、暖奶油色、深蓝海水、黑色人物剪影','温暖、奢华、宁静、日落仪式感、自然治愈、身体护理、Golden Hour氛围','lainuoniao','素材/参考站AI效果图-715张/481.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','模特仰卧于米白竖条纹亚麻布上，周边散落夏日海滩度假风道具的俯拍场景','Female model lying on beige and white striped linen fabric, holding a white cosmetic bottle with metallic gold cap gently against her cheek. She wears a matching striped sundress, her skin glowing with natural sun-kissed radiance. Warm directional sunlight creates dappled shadows across the scene, with soft fill and subtle rim light outlining her shoulders. Surrounding props include a woven straw tote bag, fresh lemon slices, dried yellow flowers, and a wooden tray with a glass of water. Shot from a top-down angle at eye level, 50mm lens, shallow depth of field with soft focus transitions. Bright and airy commercial beauty aesthetic, warm golden color grading, high-end product photography, clean retouching, blank label on bottle.','女性模特仰卧于米白竖条纹亚麻布上，手持白色化妆品瓶（金色金属瓶盖）轻贴脸颊。她身穿同款条纹吊带裙，肌肤呈现阳光般的自然光泽。温暖的方向性阳光在场景中投下斑驳阴影，配合柔光补光与微妙的轮廓光勾勒肩部线条。周围道具包括编织草编托特包、新鲜柠檬片、干燥黄色花朵，以及盛有清水的玻璃杯木托盘。俯拍视角与模特视线齐平，50mm镜头，浅景深搭配柔和焦点过渡。明亮通透的商业美妆美学，温暖金色调色彩分级，高端产品摄影，精致修图，瓶身空白标签。','温暖 directional 阳光从左上方斜射，形成斑驳遮阳影纹，配合反光板柔和补光，肩部有清晰轮廓光勾勒','顶部俯拍视角，镜头与模特视线齐平，50mm标准焦段，浅景深聚焦面部与产品，背景自然虚化','编织草编托特包、新鲜黄柠檬切片与整果、干燥黄色球花束、木质托盘、透明玻璃水杯','米白、奶油黄、金色、浅棕、柠檬黄、自然原木色、肌肤暖调','夏日清新、自然透亮、阳光活力、洁净护肤、高端美妆、慵懒惬意','lainuoniao','素材/参考站AI效果图-715张/491.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','暖调中性色摄影棚背景，简约干净的商业美妆拍摄环境','Female model with wet dark short hair holding a matte forest green pump bottle, soft studio lighting from front-left, rim light on hair and shoulders, warm neutral beige background, medium close-up portrait, 85mm lens, shallow depth of field, clean beauty editorial style, natural skin texture with subtle glow, minimalist cosmetic product photography, professional retouching, commercial skincare advertisement aesthetic','模特手持磨砂深绿泵头瓶，左侧前柔光主光，发肩轮廓光，暖米背景，85mm中近景，浅景深，干净美容编辑风，自然肌肤微光质感，极简美妆产品摄影，专业修饰，商业护肤广告美学','主光从左前方45度柔光箱打入，面部与瓶身受光均匀，发丝边缘带柔和轮廓光，右侧反光板补暗部阴影','85mm人像镜头，中近景构图，浅景深突出面部与产品，平视视角','深绿色泵头瓶身，模特湿润短发，肌肤微光质感，棕色系裹巾','暖米色背景，深森林绿瓶身，自然肤色，棕褐发色','纯净自然，高端护肤，植物系美学，亲密优雅，干净无瑕','lainuoniao','素材/参考站AI效果图-715张/501.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','温暖抽象纸艺结构场景，流畅弯曲的纸面平台与背景折纸构成几何空间，柔和阴影延伸','Professional cosmetic product photography of three premium skincare items arranged on sculptural curved paper platforms against an abstract folded paper backdrop. Left: orange-to-cream gradient squeeze tube with minimalist circular line art. Center: tall cylindrical bottle with same gradient finish. Right: short wide jar with matching design language. Soft diffused warm lighting from upper left creates dramatic yet gentle shadows across the paper architecture. Amber and peach tonal palette with creamy off-white accents. Editorial commercial style, high-end beauty branding aesthetic, clean geometric composition, shallow depth of field keeping all products sharp, studio-grade post-production, soft grain texture, luxurious mood.','专业化妆品商业摄影，三件高端护肤品陈列于雕塑感弯曲纸艺平台上，背景为抽象折纸结构。左侧：橙至奶油白渐变软管，极简圆形线条图案；中央：同款渐变高圆柱瓶；右侧：矮广口霜罐，统一设计语言。左上柔光散射，在纸艺建筑上投射戏剧性而柔和的阴影。琥珀橙与蜜桃色调搭配奶油白点缀。编辑级商业风格，高端美妆品牌美学，几何构图干净利落，浅景深保持所有产品清晰，影棚级后期制作，柔和颗粒质感，奢华氛围。','左上主光，大面积柔光箱打造柔和渐变光质，暖橙色环境反光营造整体琥珀色调，纸面边缘有微弱轮廓光勾勒','正面平视微俯机位，85mm焦段，深景深全清晰，商业产品居中构图，三分法则布局三件产品','渐变橙色软管包装、圆柱瓶、广口霜罐、米白色旋盖与底托、折叠纸质台座与背景屏风、极简几何线条图案标签','琥珀橙、蜜桃粉、奶油白、暖米色、浅杏色','精致奢华、温柔治愈、当代简约、高端护肤、光影雕塑感、暖调氛围','lainuoniao','素材/参考站AI效果图-715张/511.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','纯深酒红渐变背景，无缝一体化暗调影棚环境','A luxurious cosmetic serum bottle photographed in a high-end commercial studio setting. The bottle features a deep burgundy frosted cap with a sleek silver metallic ring collar, a transparent cylindrical glass body revealing rich crimson-red serum inside, and an elegant diamond-cut faceted base. Soft directional key light from the front-left wraps around the form, with a dramatic inner red glow emanating through the glass body creating a mesmerizing luminous effect. Rim light subtly defines the cap edge. Clean seamless deep burgundy gradient background with smooth vignette falloff. Subtle mirror reflection on the surface beneath. Shot at eye level with an 85mm lens, moderate depth of field keeping the entire product crisp while the background softly dissolves. Impeccable post-processing with rich color grading emphasizing the deep wine and ruby tones. Blank label surface with minimalist typography space.','一支奢华 cosmetic 精华瓶在高端商业影棚中拍摄。瓶身配有深酒红磨砂瓶盖和精致银色金属环领口，透明圆柱形玻璃瓶身透出浓郁的宝石红色精华液，底部饰有优雅的钻石切割纹理。柔和的定向主光从左前方照射，瓶身内部透出戏剧性的红色辉光，营造迷人的发光效果。边缘光微妙勾勒瓶盖轮廓。干净的无缝深酒红渐变背景，柔和的暗角过渡。下方表面有微妙的镜面反射。85mm镜头正面平视拍摄，中等景深使整个产品清晰锐利，背景柔和虚化。完美的后期处理，丰富的色调强化深葡萄酒与红宝石色调。空白标签表面预留极简排版空间。','正面柔光主光从左前方照射，瓶身内部透出红色辉光，顶部与边缘有柔和轮廓光，底部轻微反射','正面平视机位，中焦段约85mm，中等景深，产品居中构图，商业静物标准视角','深色酒红磨砂瓶盖，透明玻璃瓶身，银色金属环装饰，钻石切割纹理底座，光滑反射地面','深酒红，勃艮第红，暗栗色，银色金属，透明玻璃，深紫色背景','奢华，神秘，夜间护肤，精致，高级感，静谧，优雅','lainuoniao','素材/参考站AI效果图-715张/529.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','浅蓝色系圆润鹅卵石铺满画面，产品居中放置其上','Top-down flat-lay commercial product photography of a cosmetic pump bottle resting on a bed of smooth rounded stones in varying shades of pale blue and aquamarine. The bottle features a clear acrylic body with a matte light blue cylindrical base and matching pump dispenser. Soft diffused overhead studio lighting creates a dreamy, hydrated aesthetic with gentle highlights on the stones. Clean minimal composition centered framing, all elements in sharp focus with even depth of field. High-end skincare packaging shoot with serene spa-like mood, soft tonal palette, pristine clean visual language.','俯拍平面布局商业产品摄影，护肤品按压瓶放置在层层浅蓝与青玉色光滑鹅卵石之上。瓶身为透明亚克力材质，搭配哑光浅蓝色圆柱瓶底与同色按压泵头。柔和漫射顶光营造梦幻水润质感，石面呈现细腻高光。极简居中构图，全画面景深锐利。高端护肤包装拍摄，宁静SPA氛围，柔和色调，纯净高级视觉语言。','柔和漫射主光从上方均匀洒落，光线偏软无明显硬阴影，石头表面有细腻高光，整体无明显轮廓光与反光板痕迹','垂直俯拍（flat lay），中焦段，全画面景深，所有鹅卵石与产品均清晰锐利','光滑圆形鹅卵石、透明亚克力泵头瓶、哑光浅蓝色瓶身、白色按压泵芯','冰蓝色、浅天蓝、雾蓝、半透明清透白、深灰黑文字点缀','纯净,清新,宁静,高级,水润感,极简美学,SPA风格,清爽治愈','lainuoniao','素材/参考站AI效果图-715张/539.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','清澈水面漂浮着粉色与淡橙色玫瑰花的自然水景','Commercial product photography of three elegant glass skincare bottles and a cream jar with polished gold caps, placed gently on clear rippling water surrounded by floating pink and peach roses. Soft diffused natural lighting highlights the transparency and metallic reflections. Shallow depth of field blurs the aquatic background. Shot at a slightly elevated angle with a 50mm lens for crisp detail and dreamy atmosphere. Post-processed with gentle color grading enhancing pastel tones and water refractions. Blank label surfaces for branding flexibility.','商业产品摄影：三款优雅玻璃护肤品瓶与面霜罐配抛光金盖，轻置于清澈微漾水面，环绕漂浮粉橙玫瑰。柔和漫射自然光凸显玻璃通透感与金属反光。浅景深虚化水生背景。略高角度拍摄，50mm镜头捕捉锐利细节与梦幻氛围。后期调色强化粉彩色调与水波纹理。标签留白便于品牌定制。','柔和自然光从侧上方洒落，金色瓶盖产生高光反射，水面泛起波光粼粼的轮廓光','中近景俯拍视角，浅景深虚化背景，突出产品主体','透明玻璃瓶身、金色金属瓶盖、白色磨砂面霜罐、粉色玫瑰、淡橙色花朵、绿叶、清水','玫瑰粉、淡杏色、乳白、香槟金、水蓝绿','浪漫、奢华、清新、自然、柔美','lainuoniao','素材/参考站AI效果图-715张/550.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','极简自然主义场景，产品置于湿润的黑色岩石上，背景为淡蓝白色渐变，搭配绿植装饰','Commercial product photography of a vertical cosmetic squeeze tube with a sleek metallic silver body and matte black cap, featuring a blank minimalist label. The tube stands on a wet, dark volcanic rock surface scattered with glistening water droplets. Tall glossy green leaves frame the composition in the background, with a single water droplet clinging to a leaf tip. Soft, diffused studio lighting with a subtle rim light on the left edge, set against a clean pale blue-to-white gradient background. Eye-level angle, shallow depth of field, crisp focus, high-end skincare aesthetic.','商业产品摄影：一支直立的化妆品软管，拥有流畅的金属银色瓶身和哑光黑瓶盖，标签留白极简。软管立于散落着闪光水珠的湿润黑色火山岩表面上。高大的亮面绿色叶片在背景中构框，一片叶尖挂着单滴水珠。柔和的漫射影棚光，左侧边缘带有微妙的轮廓光，背景为干净的淡蓝白渐变。平视角度，浅景深，焦点清晰，高端护肤美学。','柔和的正面漫射主光，左侧带有微妙的轮廓逆光勾勒管身边缘，无明显硬阴影','平视中景镜头，浅景深，焦点清晰地落在产品主体，背景平滑虚化','湿润的黑色火山岩石，带有水珠的亮面绿色热带叶片，散落水珠','金属银，哑光黑，深翠绿，板岩灰，冰蓝色','极简，清新，纯净，自然，高端，宁静，有机护肤','lainuoniao','素材/参考站AI效果图-715张/560.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','纯白无缝哑光背景，极简静物台，阳光照射的白色纸面','High-end commercial product photography of two rectangular glass perfume bottles, one containing pale green liquid and the other pale yellow, featuring geometric crystal caps and minimalist blank white labels. Shot on a seamless white paper surface under strong directional sunlight, creating sharp diagonal shadows and brilliant caustic light refractions at the base. Bright, airy aesthetic with a clean minimalist composition. Soft focus on the background, sharp detail on the glass textures and liquid clarity. 8k resolution, photorealistic, sun-drenched atmosphere.','高端商业产品摄影，两瓶方形玻璃香水瓶，一瓶呈淡绿色液体，一瓶呈淡黄色液体，配有几何水晶瓶盖和极简空白标签。拍摄于无缝白色纸面上，强烈的定向阳光投射出锐利的对角线阴影，底部有明亮的玻璃焦散折射光。明亮清新的美学，干净的极简构图。背景柔和失焦，玻璃质感和液体清晰度细节锐利。8k分辨率，照片级真实感，阳光明媚的氛围。','强侧逆光（模拟午后阳光），硬光质感，投射出锐利的长对角线阴影，瓶底有玻璃折射产生的明亮焦散光斑','高角度45度俯拍，中焦段镜头（约50mm），画面边缘清晰，景深适中，强调瓶身轮廓','方形透明玻璃香水瓶（一绿一黄液体），水晶切割几何瓶盖，无其他杂物','纯白, 奶油黄, 淡青绿, 银灰色, 透明','奢华, 清新, 夏日, 极简, 优雅, 阳光明媚, 通透','lainuoniao','素材/参考站AI效果图-715张/570.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','柔焦渐变背景，从浅蜜桃粉过渡到暖橘色，无具体场景元素','Two amber glass dropper bottles of vitamin C serum lying at angle on soft peach-to-coral gradient surface, golden serum puddles scattered around, white dropper caps, clean minimalist aesthetic. Soft overhead diffused lighting with gentle rim highlights and warm shallow shadows. High-angle 45-degree composition with moderate depth of field keeping both bottles sharp. Commercial beauty product photography, luxurious skincare still life, warm honey tones, glossy wet liquid textures, soft gradient background, pristine studio quality, subtly desaturated warm post-processing.','两个琥珀色玻璃滴管瓶装的维生素C精华斜置于柔和蜜桃粉至珊瑚橙渐变表面，金色精华液池散落周围，白色滴管头，极简干净美学。顶部柔光照明带柔和边缘高光与温暖浅阴影。45度高角度构图，中等景深保持两瓶清晰。商业美容产品摄影，奢华护肤静物，温暖蜂蜜色调，光泽湿润液体纹理，柔焦渐变背景，精致工作室品质，轻微去饱和温暖后期处理。','顶部柔光主光，光质细腻偏软，产品边缘有轻微轮廓高光，阴影柔和不锐利，反光板补光消除暗部死黑','高角度俯拍，约45度视角，中焦段，景深适中前后两瓶均有清晰度','琥珀色方形玻璃滴管瓶，白色滴管头，透明精华液池，金色 Serum 液体泼洒痕迹','琥珀橙，蜜桃粉，暖橘，米白，浅杏色，珊瑚粉','温暖，奢华，纯净，护肤，阳光，水润，高端','lainuoniao','素材/参考站AI效果图-715张/580.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','瓶身置于天然粗粝岩石台面上，背景为柔和虚化的暖金色沙丘远景，旁侧点缀翠绿植物枝叶与玻璃烧瓶','A luxury skincare essence bottle with a matte white ribbed glass body and polished gold electroplated dropper cap, placed on a rough natural stone surface. Warm golden-hour side lighting creates soft rim highlights on the metallic cap. In the background, softly blurred desert dunes bathed in amber glow, with fresh green plant stems on the right and a transparent glass lab flask on the left. Shallow depth of field at f/2.8, 85mm lens, eye-level composition. Clean commercial product photography, high-end editorial finish, subtle post-processing with warm color grading and soft contrast enhancement.','一瓶奢华护肤精华，哑光白色竖纹玻璃瓶身搭配抛光电镀金滴管盖，置于天然粗糙岩石台面上。温暖的黄金时刻侧光在金属瓶盖边缘形成柔和轮廓高光。背景为柔焦虚化的沙漠沙丘，沐浴在琥珀色光晕中，右侧有新鲜绿色植物枝叶，左侧可见透明玻璃实验室烧瓶。f/2.8浅景深，85mm镜头，平视构图。干净的商业产品摄影风格，高端杂志级质感，后期暖色调处理配合柔和对比度增强。','主光来自左前方侧光，暖调黄金时刻柔光，瓶身金属边缘带有细腻轮廓高光，背景呈现雾状逆光晕染，整体光质柔和温润','平视中近景，85mm焦段，浅景深大光圈虚化背景与前景道具，画面层次分明','天然岩石、绿色植物枝叶、透明玻璃烧瓶、白色哑光滴管瓶身、电镀金色瓶盖','哑光白、奢华金、暖沙米色、草木绿、琥珀金','奢华高级,自然纯净,科学护肤,匠心品质,温润优雅','lainuoniao','素材/参考站AI效果图-715张/590.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('gift-set','纯白无缝背景，极简主义工作室环境','Two rectangular clear glass serum bottles with faceted vertical detailing, silver metallic dropper caps with black rubber bulbs, arranged diagonally on a seamless white reflective surface. Soft directional studio lighting from upper left, subtle rim highlights on glass edges, gentle shadow cast to the right. 45-degree high-angle close-up shot, shallow depth of field with foreground bottle in sharp focus and background bottle softly blurred. Clean minimalist aesthetic, luxury skincare product photography, crisp reflections, commercial retouching, high-end cosmetic campaign style, neutral cool-toned palette, no text or branding visible','两只长方形透明玻璃精华液瓶身，带有垂直棱纹细节，银色金属滴管盖配黑色橡胶吸球，斜向排列于无缝白色反光台面上。左上方柔和定向影室光，玻璃边缘微妙轮廓高光，右侧柔和投影。45度俯拍近景，浅景深，前景瓶清晰对焦、背景瓶柔和虚化。极简美学，高端护肤产品摄影，清晰反射，商业级精修，奢华美妆广告风格，中性冷调配色，无文字或品牌标识','左上方柔和主光，侧逆光勾勒轮廓，金属表面高光反射，右侧柔和阴影过渡','45度俯拍，微距/近摄，浅景深，焦点在前景瓶身','透明玻璃滴管瓶，银色金属泵头，黑色橡胶吸球，光滑白色反光台面','纯白，透明玻璃，银灰色，深黑色，冷调灰白','极简，高端，纯净，专业，临床感，现代，精致','lainuoniao','素材/参考站AI效果图-715张/600.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','简约的米杏色影棚背景，干净柔和无杂物的美妆拍摄环境','A beauty editorial portrait of a young woman with wavy chestnut brown hair holding a sky-blue matte squeeze tube against her cheek. Soft diffused key light from the front-left creates luminous glowing skin with subtle shadows. Warm rim light accentuates hair texture. Creamy beige seamless backdrop. Shallow depth of field at 85mm, medium close-up framing. Gentle, hydrated, clean aesthetic. Soft post-processing with warm color grading, slight film grain. Blank label on the tube. Commercial skincare campaign photography, high-end beauty look.','美妆 editorial 肖像，年轻女性栗棕色波浪发将天空蓝哑光软管贴于脸颊。左前方大面积柔光营造通透发光肤质，微妙阴影。温暖轮廓光强调发丝质感。米杏色无缝背景。85mm浅景深中近景。清新水润纯净美学，柔和后制暖色调分级微胶片颗粒。管身空白标签。高端商业护肤大片摄影。','主光来自左前方大面积柔光箱，光质柔软均匀，右侧微弱补光消除阴影，发丝有温暖轮廓光勾勒，肤色呈现通透自然光泽','85mm人像焦段，肩部以上中近景构图，浅景深虚化边缘，平视角度，焦点落在面部与产品上','淡蓝色软管包装洁面产品，女性模特双手托举，裸露肩颈肌肤，波浪短发造型','米杏色背景,天空蓝产品,暖调自然肤色,巧克力棕发色,淡粉色唇妆,奶油白高光','清新自然,纯净水润,高级美妆,松弛优雅,温和护肤,质感通透,女性魅力,静谧温柔','lainuoniao','素材/参考站AI效果图-715张/601.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','纯净科技感蓝色渐变背景的工作台场景，带有绘图网格线','A luxury cosmetic bottle with cobalt blue gradient glass and brushed silver cap, held gently by two sleek chrome robotic arms on both sides. The bottle stands upright on a pristine white drafting grid surface. Soft studio lighting from above creates elegant highlights on the glass body and metallic surfaces, with a subtle blue rim glow. Clean blue gradient background fading from light to deep azure. Symmetrical centered composition, eye-level shot, 50mm lens, commercial product photography style, sharp focus on the bottle, ultra-clean post-processing, high-end beauty tech aesthetic.','一款奢华化妆品瓶，钴蓝色渐变玻璃瓶身搭配拉丝银盖，被两侧优雅抛光的铬色机械臂轻轻夹持。瓶子立于纯白绘图纸网格台面上，顶部柔光在玻璃瓶身和金属表面形成精致高光，边缘带有微妙蓝色轮廓光。干净的蓝渐变背景由浅至深过渡。对称居中构图，平视角度，50mm镜头，商业产品摄影风格，焦点锐利集中于瓶身，极致干净的后期处理，高端美妆科技美学。','顶部主光柔光照明，瓶身两侧有金属轮廓光，右侧机械臂有高光反射，整体为干净影棚布光','正面平视机位，50mm焦段，中心对称构图，中等景深使前景与主体清晰聚焦','蓝色渐变玻璃化妆品瓶、银色金属瓶盖、双机械臂夹具、白色网格图纸台面','钴蓝色,天蓝渐变,银铬色,白色,淡灰蓝','未来感,精密,科技美学,奢华,专业,洁净','lainuoniao','素材/参考站AI效果图-715张/609.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','粉色方格瓷砖墙面搭配左侧垂落的哑光粉色布帘，简洁干净的美妆产品拍摄环境','Commercial beauty product photography of a woman''s hands squeezing a pastel pink tube with a deep burgundy flip-cap, a dollop of thick white cream falling into the palm below. Soft frontal diffused key light with rim light defining the tube edges, no harsh shadows. Background: pale pink grid tiles on wall with draped soft pink fabric curtain on left. Eye-level medium shot, 50mm lens, shallow depth of field keeping hands and tube sharp. Clean flat-lay editorial style, bright and airy aesthetic. Blank label on tube. Post-processed with subtle color grading for a warm pink-dominant palette.','商业美妆产品摄影：女性双手挤压一支浅粉色软管，搭配酒红色旋盖，白色浓稠乳霜挤出落入掌心。正面柔光主光，侧后方轮廓光勾勒瓶身，无硬阴影。背景为浅粉色方格瓷砖墙，左侧垂挂柔软粉色布帘。平视中景，50mm镜头，中等景深保证双手与产品清晰。干净扁平化编辑风格，明亮轻盈美学。瓶身标签留白。后期微调暖粉色调为主。','正面柔光箱主光+侧后方轮廓光勾勒瓶身边缘，浅粉色墙面充当大型反光板补光，瓶身呈现均匀柔和高光无硬阴影','正面平视机位/50mm焦段/中景景深覆盖双手与产品/平行视角构图居中','女性双手、粉色软管护肤品容器、酒红色旋盖、白色乳霜质地挤出物、粉色方格瓷砖背景墙、左侧粉色织物帘','浅粉色、深粉色、酒红色、白色、肤色','温柔甜美、清爽洁净、少女感、精致美妆、护肤仪式感、柔和梦幻','lainuoniao','素材/参考站AI效果图-715张/617.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','纯白摄影棚背景，极简美妆广告拍摄场景','Beauty campaign photography, a diverse woman holding a sleek metallic silver sachet packaging with vibrant lime green typography across her lips, soft studio lighting from a large front softbox, clean white seamless background, medium close-up portrait at eye level, 85mm lens with moderate depth of field keeping both face and product sharply in focus, subtle rim light defining hair edges, flawless airbrushed skin retouching, high-end cosmetic advertising aesthetic, glossy lip finish, natural wavy hair, minimalist luxury beauty commercial style, fashion magazine quality --ar 4:5 --v 6 --style raw','美妆广告摄影，一位多元肤色女性将精致的金属银色软管包装轻贴于唇间，荧光柠檬绿色字体醒目，大型正面柔光箱提供柔和影棚光效，纯白无缝背景，眼睛高度的中近景人像，85mm镜头中等景深确保面部与产品均清晰锐利，轮廓光勾勒发丝边缘，无瑕磨皮质感，高端美妆广告美学，光泽唇妆，自然微卷发型，极简奢华美妆商业风格，时尚杂志级别品质 --ar 4:5 --v 6 --style raw','正面柔光主光（大型柔光箱），辅光板补光消除阴影，轮廓光勾勒发丝边缘，整体光质柔和均匀','中近景人像视角，约85mm人像镜头，中等景深保留面部与产品均清晰，平视机位','金属质感银色软管包装、金色圆环耳环、模特美甲长甲、自然卷发造型','银灰色主调、荧光柠檬绿文字点缀、纯白背景、暖调肤色、金色配饰','清新、专业美妆、高级感、水润光泽、现代简洁、自信魅力','lainuoniao','素材/参考站AI效果图-715张/634.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','年轻女性盘腿坐在米色背景前，身穿白色丝绸吊带裙，双手轻托瓶身置于膝间，阳光从右侧洒落','A serene beauty editorial shot of a young Asian woman with short dark hair, wearing a white silk slip dress, sitting with knees drawn up against a warm beige wall. Sunlight streams softly from the right side, casting gentle shadows and a delicate rim light on her collarbone and shoulder. She cradles a matte pale mint-green pump bottle between her hands and knees; the bottle features minimalist botanical line art and a blank label area. Natural window light, soft diffused quality with subtle fill from a reflector on the left. Shot on 85mm lens at eye level, shallow depth of field keeping the bottle and face sharp while skin tones glow warmly. Clean, uncluttered composition embodying quiet luxury and holistic wellness aesthetics.','一幅宁静的美容大片，年轻亚洲短发女性身穿白色丝绸吊带裙，盘腿坐于暖米色墙面之前。柔和的右侧窗光洒落，在锁骨与肩部勾勒出细腻轮廓光，左侧反光板柔化阴影。她双手环抱一只磨砂薄荷绿按压泵瓶置于膝间，瓶身饰以极简植物线条图案，标签区域留白。自然光质感柔和漫射，85mm焦段平视拍摄，浅景深让瓶身与面部清晰锐利而肤色温润发光。构图干净克制，诠释静谧奢华与整体疗愈美学。','右侧自然侧光主光，柔和漫射质感，右肩与锁骨处有温暖轮廓光，左侧反光板补光柔化阴影','中景平视构图，约85mm焦段，浅景深，焦点集中在瓶身与模特面部，边缘自然柔焦','米白色丝绸吊带裙，磨砂薄荷绿按压泵瓶，植物线条手绘图案，纯色米色背景墙面','薄荷绿，米白，奶油色，暖肤色，浅灰绿，米色阴影','宁静，自然奢华，疗愈感，极简主义，温柔纯净，高端护肤美学','lainuoniao','素材/参考站AI效果图-715张/651.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','极简米色纹理背景，搭配矩形镜面反射道具','Professional commercial product photography of an amber square glass bottle with a black ribbed cap and a blank cream-colored label, standing on a textured beige surface. A rectangular mirror beside it reflects a cluster of fresh black currants. Soft diffused lighting with gentle side rim light enhancing the glass transparency. Clean minimalist aesthetic, shallow depth of field, high-end skincare editorial style, neutral earthy palette, crisp focus on product, 85mm lens equivalent, studio setup.','专业商业产品摄影，琥珀色方形玻璃瓶搭配黑色螺纹旋盖和空白米色标签，置于纹理米色台面上。旁边的矩形镜子反射出一簇新鲜黑加仑。柔和漫射光，侧面轮廓光增强玻璃通透感。极简干净美学，浅景深，高端护肤品编辑风格，中性大地色系，产品聚焦清晰，等效85mm镜头，摄影棚布光。','柔和漫射主光，侧面轮廓光勾勒瓶身，反光板补光，无硬阴影','中近景平视略带俯角，浅景深突出主体，焦内锐利焦外柔化','琥珀色方形玻璃瓶，黑色螺纹旋盖，米白色标签，矩形平面镜，黑加仑果实','米白，奶油色，琥珀棕，深黑，自然灰','纯净，有机，高端，宁静，极简主义，自然系','lainuoniao','素材/参考站AI效果图-715张/659.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','户外花园绿植环境，阳光透过树叶洒下斑驳光影','A young Asian woman with shoulder-length dark hair wearing an ivory silk blouse, gently holding a cosmetic bottle with a yellow-to-orange gradient liquid and a round spherical cap against her chest. She gazes softly to the side with a serene expression. Lush green garden foliage fills the background with dappled sunlight filtering through leaves, creating natural bokeh. Shot with a 85mm lens at f/1.8, shallow depth of field separating subject from background. Soft natural backlight creates delicate rim light on her hair. Neutral color grading, film-like warmth, high-end commercial beauty photography, lifestyle aesthetic.','一位年轻亚洲女性，深棕色及肩发，身穿奶油白色丝绸衬衫，将一瓶黄橙渐变液体的化妆品轻贴胸前，瓶盖为圆润球形设计。她温柔地望向一侧，神情恬静。背景是繁茂的绿色花园，阳光透过树叶形成斑驳光斑与柔美的焦外虚化。85mm镜头f/1.8拍摄，浅景深突出主体。柔和的自然逆光在发丝边缘形成精致轮廓光。中性色彩调校，胶片感暖调，高端商业美妆摄影，生活方式美学风格。','自然侧逆光为主，柔和散射光，发丝轮廓光明显，背景虚化光斑，无明显反光板补光','中近景人像机位，50mm-85mm焦段，浅景深大光圈虚化背景，平视视角','模特手持化妆品瓶、前景绿叶虚化、背景茂密绿植','薄荷绿、嫩叶黄、暖杏橙渐变、奶油白、自然肤色、深棕发色','清新自然、柔和恬静、有机纯净、生活方式感、日系写真','lainuoniao','素材/参考站AI效果图-715张/667.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','纯色粉色渐变背景，产品密集阵列排列','Top-down flat-lay commercial product photography of hexagonal pressed powder compacts in vibrant pink gradient tones, arranged in a precise repeating grid pattern filling the frame. Matte plastic packaging with smooth round lids, subtle metallic gold typography printed on blank labels. Soft overhead diffused studio lighting with even illumination, minimal shadow depth, clean rim light separating each unit. Sharp focus across entire array, symmetrical composition, high-end beauty branding aesthetic, post-processing with vibrant saturation and clean color grading.','垂直俯拍商业产品摄影，六边形粉饼盒以活力粉色渐变色调排列，精确重复网格图案填满画面。哑光塑料包装配光滑圆形盖，空白标签上印有精致的金属金色文字。顶部柔光棚灯均匀照明，阴影浅淡，边缘轮廓光分离每个单元。全阵列锐利对焦，对称构图，高端美妆品牌美学，后期处理 vibrant饱和度与干净调色。','顶部柔光主光，均匀铺光无明显阴影，边缘有轻微轮廓光分离层次，反光板补暗部','垂直俯拍视角，50mm焦段，全景深，无限远对焦','六边形粉饼盒，圆形粉饼盖，哑光塑料材质，金属质感印刷字体','深玫红，柔和粉红，淡粉，金色细字','精致，时尚，女性化，高端美妆，整齐秩序感，商业产品摄影','lainuoniao','素材/参考站AI效果图-715张/676.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','梦幻云境中的几何展台，产品仿佛悬浮于柔软白云之上，背景为纯净渐变浅蓝','Studio commercial product photography of a frosted semi-translucent body wash pump bottle in soft powder blue, resting on a geometric pedestal surrounded by voluminous fluffy white clouds. Ethereal dreamlike atmosphere against a seamless gradient sky-blue backdrop. Soft front key lighting with subtle rim light defining the bottle silhouette, gentle cloud diffused fill eliminating harsh shadows. Medium close-up, slightly low angle, shallow depth of field with foreground cloud softness. Clean minimalist aesthetic, high-end skincare branding style, polished 3D render quality, ultra-detailed product shot.','影棚级商业产品摄影，磨砂半透明浅粉蓝色身体乳按压瓶，置于几何展台上，环绕蓬松白云。梦幻空灵氛围，无缝渐变天空蓝背景。正面柔光主光配合微妙轮廓光勾勒瓶身，柔和云层漫射填充消除硬阴影。中近景略低角度，浅景深前景云朵虚化。极简干净美学，高端护肤品牌风格，精致3D渲染质感，超细节产品展示。','正面柔光主光均匀照亮瓶身，侧逆光勾勒轮廓与材质层次，底部无反板填充，光影柔和干净无硬边','正面上升机位，中近景构图，浅景深突出产品主体，云朵前景略带虚化增加空间层次','白色蓬松云朵/棉絮质感道具，浅蓝色几何立方体展台，磨砂半透明瓶身按压泵头瓶','浅粉蓝，纯白，银金属色，柔和渐变蓝色调','梦幻，纯净，轻盈，极简，清新，治愈系，高级感，水润舒缓','lainuoniao','素材/参考站AI效果图-715张/684.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','纯色粉色背景前的多支口红竖立阵列，每支口红后衬有同色系渐变阴影板','Commercial beauty product photography of multiple vertical lipstick tubes arranged in a staggered grid against a solid pastel pink backdrop. Each lipstick features a metallic silver cap and a matte white square body with a blank label, showcasing vibrant bullet colors ranging from nude beige to deep berry and fuchsia. Behind each tube, a matching gradient-colored shadow panel creates depth. Hard directional studio lighting from above casts sharp, clean shadows. Shot straight-on with a 50mm lens, deep depth of field, all products in crisp focus. High-end cosmetic advertisement style with saturated yet refined color palette.','商业彩妆广告摄影，多支竖立口红以错落阵列排列在柔粉纯色背景前。每支口红均为金属银盖搭配哑光白方柱外壳，空白标签，膏体色彩从裸米色至深莓红、玫红渐变。每支后方配有同色系渐变阴影卡板营造层次。上方硬光直射，投下锐利干净阴影。正面平视拍摄，50mm镜头，深景深，全产品清晰对焦。高端化妆品广告风格，色彩饱和而精致。','硬光主光从正侧上方投射，形成清晰锐利的投影，高反差商业影棚光效，轮廓光强化金属管身质感','正面平视机位，中焦段（约50mm），全画幅深景深，所有口红均清晰对焦，平铺构图','金属银色口红管身、哑光白色方柱形外壳、彩色口红膏体、渐变色背景卡板、纯粉背景纸','柔粉、玫红、珊瑚红、深莓红、裸米色、银白、纯黑文字','现代、精致、时尚、彩妆广告、色彩饱和、干净利落、高级感','lainuoniao','素材/参考站AI效果图-715张/693.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','户外复古花纹地砖场景，阳光斑驳洒落，搭配多肉植物盆栽营造地中海风格氛围','Professional cosmetic product photography of a frosted translucent pump bottle filled with pale yellow body wash, black pump dispenser, minimalist white blank label with elegant typography, placed on vintage Mediterranean patterned tiles in dusty blue and warm beige tones, dappled sunlight casting sharp leaf shadows across the scene, a potted succulent plant nearby adding organic texture, hard directional natural light from upper left creating strong contrast and glowing highlights on the bottle curves, golden hour warm color grading, shallow depth of field with crisp product focus, editorial commercial aesthetic, shot on medium format digital camera with lens flare accents, high-end skincare brand lifestyle imagery','专业化妆品产品摄影，半透明磨砂按压泵瓶盛装淡黄色沐浴露，黑色泵头，极简白色空白标签配优雅字体，置于复古地中海风格花纹地砖上，灰蓝色与暖米色调，斑驳阳光投射清晰树叶阴影，旁边摆放多肉植物盆栽增添自然质感，强烈侧向自然光从左上方照射形成高对比度与瓶身曲线发光高光，金色时段温暖色调分级，浅景深精准聚焦产品，杂志级商业美学，中画幅数码相机拍摄带镜头光晕，高端护肤品牌生活方式影像','强烈侧向自然日光从左上方照射，形成硬朗清晰的投影与树影斑驳效果，金色时段温暖光质勾勒瓶身轮廓光','平视微俯角中近景构图，35mm定焦镜头，f/4中等景深保留环境细节同时突出产品主体','半透明磨砂按压泵瓶、复古蓝色花纹地砖、多肉植物、赤陶花盆、自然树叶阴影','暖米色、灰蓝色、焦糖棕、淡黄色液体、黑色泵头、白色标签、薄荷绿植物','自然有机、地中海风情、阳光沐浴、简约高端、 wellness lifestyle、复古文艺、温暖宁静','lainuoniao','素材/参考站AI效果图-715张/701.jpg');
INSERT INTO render_prompts (category,scene,prompt_en,prompt_zh,lighting,camera,props,palette,mood,src,sample_img) VALUES ('lifestyle','阳光明媚的海滩背景，远处可见柔和的蓝色海洋与沙滩，自然户外环境','A close-up beauty campaign photograph of a woman with curly brown hair and warm tan skin holding an open rectangular rose gold makeup compact with two matte mauve-brown powder pans, blank label, against a softly blurred sunny beach backdrop with ocean blue. Shot in golden hour natural side lighting with a slight warm tone, soft catchlights in eyes, dewy luminous skin texture. 85mm lens, shallow depth of field, eye-level composition, cinematic commercial retouching, high-end cosmetics advertisement style, rich warm color grading.','一张美妆广告特写照片，一位卷发深棕肤色女性手持打开的玫瑰金双色方形彩妆盘（空白标签），背景为虚化的阳光明媚海滩与蓝色海洋。黄金时段自然侧光，微微暖调，眼神光清晰，肌肤呈现水润光泽质感。85mm镜头，浅景深，平视构图，电影级商业修图，高端化妆品广告风格，丰富的暖色调色彩分级。','自然日光侧光照明，黄金时段暖调光线，人物面部左侧主光柔和偏硬，右侧有轻微反光板补光，轮廓光勾勒头发边缘，眼部有明显眼神光','中近景人像特写，约85mm焦段，浅景深虚化背景，与人物视线平齐的机位，焦点精准落在面部与产品上','玫瑰金外壳双色腮红/修容盘，纤细金色圆圈耳环，细金链项链，简约细金戒指，裸粉色美甲','玫瑰金，灰玫瑰粉，暖棕色调，沙色米白，柔和天蓝，肤色暖棕','夏日阳光感，高级美妆广告，自然光泽肌，轻松优雅，自信迷人，高端商业质感','lainuoniao','素材/参考站AI效果图-715张/709.jpg');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('dropper-bottle','石台丝绸·精华滴管','A {color} {material} {product} with a {cap} cap and a blank minimalist label, centered on a raw-edged white limestone slab. Draped nude silk flows behind as a soft background, a few stems of baby''s breath entering from the upper right, three glistening water droplets on the slab. Soft diffused key light from the upper left with a white reflector fill, subtle rim light outlining the bottle, crisp specular highlight on the cap. Eye-level, 85mm lens, shallow depth of field with creamy bokeh. Clean minimalist composition, high-end commercial beauty photography, soft warm color grading, no visible branding or text.','{color}{material}{product},{cap}盖,空白极简标签,居中置于粗边白色石灰石台上;身后垂坠裸色丝绸,右上伸入满天星,台面三滴水珠。左上柔光主光+白反光板补光,瓶身轮廓光,盖子高光。平视 85mm 浅景深奶油散景。极简高端商业美妆摄影,暖调,无品牌无文字。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('dropper-bottle','森林苔木·自然精华','A {color} {material} {product} with a {cap} cap and a blank label resting on a moss-covered fallen log in a serene forest. Lush ferns, tiny white wildflowers and smooth river stones around it. Dappled golden sunlight filters through the canopy, soft organic shadows, gentle rim light on the bottle edge. Slightly high angle, 85mm lens, f/2.8, sharp product with a dreamy blurred background. Fresh organic mood, mint green and cream palette, high-end skincare campaign, 8k, hyper-realistic textures, no branding.','{color}{material}{product},{cap}盖,空白标签,放在宁静森林里长满青苔的原木上;周围蕨类、白色小野花、圆润河石。斑驳金色阳光透过树冠,柔和自然阴影,瓶身边缘轮廓光。微俯 85mm f/2.8,主体锐利背景梦幻虚化。清新有机,薄荷绿与奶油白配色,高端护肤大片,8k 超写实,无品牌。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('jar','大理石乳霜·水珠','A {color} {material} {product} with a {cap} lid and a blank label standing on a smooth white marble surface, surrounded by swirling creamy white lotion texture and glistening water droplets. Soft diffused studio key light from the front-left, gentle specular highlight on the lid, subtle rim light, white bounce fill, no harsh shadows. Medium close-up, eye-level, 85mm f/1.4, jar tack-sharp with softly blurred background. Clean luxurious spa mood, fresh premium skincare aesthetic, high-end commercial retouching, clean color grading, no branding.','{color}{material}{product},{cap}盖,空白标签,立于光滑白色大理石台面,周围环绕旋涡状乳霜纹理与晶莹水珠。前左柔光主光,盖子高光,微妙轮廓光,白反光板补光,无硬影。中近景平视 85mm f/1.4,罐身锐利背景柔化。奢华 SPA 氛围,清新高端护肤美学,商业精修,无品牌。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('jar','石球岩台·绿叶','A {color} {material} {product} with a {cap} lid, blank label, balanced on a polished sage-green stone sphere perched on a textured beige limestone rock, soft-focus fresh green foliage behind. Soft diffused natural window light from the left, gentle specular highlights on the lid, subtle rim light, soft shadow to the right. Medium close-up, eye-level, 85mm, shallow depth of field, sharp focus on the product. Serene organic sophisticated mood, forest green and sandstone palette, high-end skincare aesthetic, 8k, no branding or text.','{color}{material}{product},{cap}盖,空白标签,置于抛光鼠尾草绿石球上,石球搁在粗糙米色石灰岩上,背景虚化翠绿枝叶。左侧柔和窗光,盖子高光,微妙轮廓光,右侧柔影。中近景平视 85mm 浅景深,产品锐利。宁静有机高级感,森林绿与砂岩色,高端护肤,8k,无品牌无文字。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('tube','纯白棚·水珠凝胶','Extreme close-up macro shot of a {color} {material} {product} with a {cap} cap and a blank label, angled diagonally, surface covered with fine condensation droplets, a single thick gel droplet emerging from the nozzle. Gentle left-side softbox key light wrapping the curves, side fill lighting the water beads, subtle rim light, negative fill for gentle contrast. Pure white seamless background, 85mm macro, shallow depth of field with soft focus falloff. Fresh hydrating pure mood, commercial skincare photography, crisp detail, high-end beauty aesthetic, no branding.','微距特写:{color}{material}{product},{cap}盖,空白标签,对角斜置,管身布满细密冷凝水珠,一滴浓稠凝胶从管口挤出。左侧柔光箱主光包裹曲线,侧补光点亮水珠,微妙轮廓光,黑旗留反差。纯白无缝背景,85mm 微距浅景深。清新水润纯净,商业护肤摄影,超清细节,无品牌。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('tube','果蔬同源·米色台','A {color} {material} {product} with a {cap} cap and a blank label standing upright on a seamless off-white cyclorama, surrounded by fresh fruit slices and a sprig of green herb that echo the formula (citrus, apple or berry), a few water droplets on the surface. Soft diffused key light from the front-left, white bounce fill, subtle rim light, soft diagonal shadow to the right. Eye-level, 85mm, f/5.6, product sharp with foreground fruit slightly soft. Clean minimalist composition, soft pastel color grading, high-end commercial beauty photography, 8k ultra-detailed, no branding or text.','{color}{material}{product},{cap}盖,空白标签,直立于无缝米白弧形背景上,周围摆放呼应配方的新鲜果片与一枝绿色香草(柑橘/苹果/莓果),台面几滴水珠。前左柔光主光,白反光板补光,微妙轮廓光,右侧柔和斜影。平视 85mm f/5.6,产品锐利前景果片微虚。极简干净构图,柔和粉彩调色,高端商业美妆摄影,8k 超细节,无品牌无文字。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('pump-bottle','石托盘窗光·叶影','A {color} {material} {product} with a {cap} pump and a blank label standing on a round travertine stone tray on a glass-top white table, a glass candle and a wooden comb beside it. Directional sunlight through a window casts soft dappled leaf shadows across a warm grey wall behind; subtle fill reflection, crisp shadows, gentle rim light on the bottle. Eye-level with a slight high angle, 50mm, medium depth of field, wall softly blurred. Calm serene high-end spa atmosphere, cream and warm grey palette, editorial composition, photorealistic, no branding.','{color}{material}{product},{cap}泵头,空白标签,立于玻璃台面上的圆形 travertine 石托盘,旁配玻璃蜡烛与木梳。窗外斜阳在暖灰墙面投下斑驳叶影;柔和补光,阴影清晰,瓶身轻轮廓光。平视略俯 50mm 中等景深,墙面虚化。宁静高端 SPA 氛围,奶油白与暖灰色调,编辑级构图,写实,无品牌。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('pump-bottle','暗调渐变·几何展台','A {color} {material} {product} with a {cap} pump and a blank label resting on transparent iridescent geometric acrylic blocks against a smooth gradient background fading from deep coral to soft golden peach. Warm rim light from the upper right creates a luminous halo around the bottle, soft key light from the front-left, black flag for rich contrast, specular highlight on the pump. Centered vertical composition, eye-level, 85mm, shallow depth of field. Luxurious radiant premium mood, cinematic warm color grading, 8k, hyper-realistic textures, no branding or text.','{color}{material}{product},{cap}泵头,空白标签,置于透明虹彩几何亚克力块上,背景由深珊瑚渐变至柔和金桃色。右上暖色轮廓光在瓶身形成光环,前左柔光主光,黑旗加反差,泵头高光。居中竖构图,平视 85mm 浅景深。奢华温润高级感,电影级暖调,8k 超写实质感,无品牌无文字。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('gift-set','纸艺台阶·同款套装','A matching set of three {color} {material} {product} pieces with {cap} caps and blank labels, sharing one design language, arranged on stepped paper-art platforms in warm cream tones against a seamless paper backdrop. Soft key light from the upper left, subtle rim light on every edge, white bounce fill, clean gentle shadows. Eye-level, 85mm, deep depth of field keeping all products sharp, rule-of-thirds horizontal arrangement with generous negative space. Elegant gift-set presentation, warm minimal palette, high-end commercial beauty photography, clean retouching, no branding or text.','同一设计语言的三件{color}{material}{product}套装,{cap}盖,空白标签,陈列于暖奶油色纸艺台阶展台上,无缝纸背景。左上柔光主光,每件边缘轮廓光,白反光板补光,阴影干净。平视 85mm,深景深全部清晰,三分法横排留白充足。优雅礼盒呈现,暖调极简配色,高端商业美妆摄影,精修,无品牌无文字。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('gift-set','水面花瓣·套装','A skincare set of three {color} {material} {product} bottles and one jar with {cap} caps and blank labels standing in shallow crystal-clear water with floating pale pink rose petals, gentle ripples reflecting the products. Soft top-front key light, rim light along each bottle, specular highlights on the caps, soft fill. 45-degree high angle, 85mm, deep depth of field keeping every piece sharp, products staggered front to back. Fresh luxurious serene mood, blush pink and pearl white palette, high-end commercial beauty photography, clean color grading, no branding or text.','三瓶一罐的{color}{material}{product}护肤套装,{cap}盖,空白标签,立于清澈浅水中,水面漂浮淡粉玫瑰花瓣,涟漪倒映产品。顶前柔光主光,每瓶轮廓光,盖子高光,柔和补光。45° 俯拍 85mm,深景深件件清晰,前后错落。清新奢华宁静,粉与珍珠白配色,高端商业美妆摄影,干净调色,无品牌无文字。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('lifestyle','模特手持·窗光','A young Asian woman with natural makeup and an ivory silk blouse gently holding a {color} {material} {product} with a {cap} cap and a blank label near her cheek, soft dreamy expression. Bright airy indoor setting, soft morning window light from the side-back creating an ethereal high-key glow and hair rim light, white board fill, dewy luminous skin. Product in the foreground tack-sharp, face softly focused, blurred pink flowers as bokeh. Eye-level medium shot, 85mm, shallow depth of field. Soft pastel palette, romantic fresh mood, high-end cosmetic campaign photography, clean retouching, no branding or text.','妆容自然、身穿象牙色丝质衬衫的年轻亚洲女性,将{color}{material}{product}({cap}盖,空白标签)轻贴脸颊,表情梦幻温柔。明亮室内,侧后方柔和晨间窗光营造空灵高调光与发丝轮廓光,白板补光,肌肤水润透亮。前景产品锐利、面部柔焦,粉色花卉虚化成散景。平视中景 85mm 浅景深。柔粉彩配色,浪漫清新,高端化妆品广告摄影,精修,无品牌无文字。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
INSERT INTO render_templates (category,name,template_en,template_zh,notes) VALUES ('lifestyle','手持喷雾·果蔬高调','A fair-skinned hand elegantly holding a {color} {material} {product} with a {cap} cap and a blank label, releasing a fine luminous mist. Bright airy high-key scene, soft diffused natural light from the upper right, white reflector fill, rim light catching the mist particles and water droplets, dreamy blurred background of white magnolia flowers and sliced guava with dewy droplets. Slightly elevated eye-level, 85mm, shallow depth of field with creamy bokeh, macro detail on the mist. Fresh pure hydrating mood, mint and cherry-blossom palette, editorial beauty aesthetic, soft color grading, no branding or text.','一只白皙的手优雅握着{color}{material}{product}({cap}盖,空白标签),正喷出细腻明亮的水雾。明亮通透高调场景,右上柔和漫射自然光,白反光板补光,轮廓光勾勒雾粒与水珠,背景虚化白玉兰与切开番石榴带水珠。平视略俯 85mm 浅景深奶油散景,微距雾粒细节。清新纯净水润,薄荷绿与樱花粉配色,杂志级美妆美学,柔和调色,无品牌无文字。','占位:{product} {material} {color} {cap};骨架=主体+材质+blank label → 台面/道具呼应功效 → 柔光主光+rim light+反光板 → 85mm 浅景深 → 后期词');
